(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c28"]=[{"id":"00016434","register_sub_id":"101","register_pk":"536501","name":"旧太池呉服店店舗兼主屋","kana":"きゅうおおいけごふくてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県新見市新見字小山屋851他","lat":34.98350278,"lng":133.46832222,"geo_status":"db","era":"大正2年／大正前期増築、昭和7年頃・同18年頃・平成21年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積213㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"33 - 0390","desc":"市街地中心部の角地に建つ旧呉服店の店舗兼主屋。二階建入母屋造平入桟瓦葺で北に座敷棟を接続。正面一階は平格子、二階は出格子構えで、西面は白漆喰塗大壁で各階腰を海鼠壁とする。内部一階南東部は土間で北西に座敷を配す。建ちが高く、豪壮な外観の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016434"},{"id":"00010050","register_sub_id":"101","register_pk":"196197","name":"旧岡野屋旅館客室棟","kana":"きゅうおかのやりょかんきゃくしつとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷113","lat":35.08574373,"lng":133.69050418,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0255","desc":"旭川東岸の神橋たもとに建つ木造二階建で、入母屋造桟瓦葺とする。一階に六室、二階は五〇畳の大広間にもなる五室の客室を川に面して並べ、東に廊下を通す。一階西側の縁は川岸の石垣上に迫出し、上下階ともガラス障子をたてる。河岸景観を引き立てる旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010050"},{"id":"00010051","register_sub_id":"101","register_pk":"196198","name":"旧岡野屋旅館門及び塀","kana":"きゅうおかのやりょかんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷114-1","lat":35.08567331,"lng":133.69056993,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"門 木造、銅板葺、間口2.0m 塀 木造、鉄板葺、総延長11m、潜戸付","structure_material":"門 木造","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0256","desc":"旭川に架かる旧出雲街道の神橋たもとから北に奥まって開く門。一間棟門で、内側に控柱を立てる。一軒吹寄垂木で、屋根は切妻造銅板葺である。吹寄菱格子の欄間が繊細である。門の両側に延びる板塀は鉄板葺で、七宝文の透欄間を入れる。東側塀には潜戸を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010051"},{"id":"00000169","register_sub_id":"101","register_pk":"101159","name":"旧中國銀行牛窓支店","kana":"きゅうちゅうごくぎんこううしまどしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県瀬戸内市牛窓町牛窓2835-1","lat":34.61395011,"lng":134.16786245,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，建築面積104㎡","structure_material":"煉瓦造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0015","desc":"ＲＣ造，平屋建の銀行建築で，設計は小林精一。外壁をドイツ製の煉瓦を小口積とし，軒はモルタルで蛇腹を造る。内部は吹き抜けとし，漆喰造の内壁上端に蛇腹を設け，草花の連続模様を施し，全体に簡素な仕上げになる。明治末～大正期の銀行建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000169"},{"id":"00012039","register_sub_id":"101","register_pk":"210980","name":"金光教徒社中央棟","kana":"こんこうきょうとしゃちゅうおうとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県浅口市金光町大谷325-3他","lat":34.538696,"lng":133.624687,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、スレート葺、建築面積125㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-292","desc":"東棟と西棟の間に建つ。木造二階建、寄棟造、スレート葺で、建築面積一二五平方メートル。外壁はモルタルを塗装して石積に見せる特異な外観で、パラペットを高く立ち上げて陸屋根風に見せる。内部は一階に事務室、応接室を配し、二階は現在倉庫とされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012039"},{"id":"00012040","register_sub_id":"101","register_pk":"210981","name":"金光教徒社西棟","kana":"こんこうきょうとしゃにしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県浅口市金光町大谷325-3他","lat":34.538703,"lng":133.624581,"geo_status":"db","era":"大正5年／昭和18年増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、スレート葺、建築面積76㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-293","desc":"金光教徒新聞社の社屋として大正五年に建てられたもの。木造二階建、寄棟造、スレート葺で、建築面積七六平方メートルである。中央部と西側下屋に入口を設け、外壁下見板張で、軒を板張とするなど簡素な意匠でまとめる。地域の景観を形作る洋風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012040"},{"id":"00012038","register_sub_id":"101","register_pk":"210979","name":"金光教徒社東棟","kana":"こんこうきょうとしゃひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県浅口市金光町大谷337-1","lat":34.538703,"lng":133.624804,"geo_status":"db","era":"大正10年／昭和28年増築","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、スレート葺、建築面積128㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-291","desc":"金光教本部前の広場に北面する。木造二階建、寄棟造、スレート葺で、建築面積一二八平方メートルである。切石積基礎に外壁下見板張とし、中央に入口を配する左右対称の外観が特徴。軒線中央部を僅かに切り上げ、ベディメント状に見せる。洋風意匠の事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012038"},{"id":"00000168","register_sub_id":"101","register_pk":"101158","name":"作州民芸館（旧土居銀行津山支店）","kana":"さくしゅうみんげいかん（きゅうどいぎんこうつやましてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県津山市西今町18","lat":35.0605015,"lng":133.9936987,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建，鋼板葺，建築面積284㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0014","desc":"明治30年設立の土居銀行の社屋として建てられた。ルネッサンス様式を基本としながら，多様なモチーフを用いる。木造であるが西洋古典様式風のオーダーが付く石造風の外観である。現在は資料館として用いられ，その特異な外観からひときわ目を引く存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000168"},{"id":"00010054","register_sub_id":"101","register_pk":"196201","name":"辻本店衣装蔵","kana":"つじほんてんいしょうぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷116","lat":35.0859204,"lng":133.69097242,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0259","desc":"主屋の北に接続する土蔵造二階建で、切妻造、置屋根式の桟瓦葺とする。切石基礎上に建ち、外壁は漆喰塗で、上下階の腰と隅部を海鼠壁とする。東面に戸口を設け、瓦葺庇下を濡縁とする。西の通り側の窓は、土戸の内側を鏝絵で飾り、庇持送りの彫刻も繊細である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010054"},{"id":"00010055","register_sub_id":"101","register_pk":"196202","name":"辻本店奥座敷","kana":"つじほんてんおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷116","lat":35.0860523,"lng":133.69101222,"geo_status":"db","era":"明治中期／大正期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0260","desc":"衣装蔵の北に並ぶ木造平屋建で、入母屋造桟瓦葺の東西面に下屋を廻らし、南に入母屋屋根の脇玄関を設ける。北には化粧部屋、風呂、便所が附属する。八畳主室はトコ、棚、付書院を飾り、次の間には西の表門に向けて式台玄関を開く。造作の丁寧な離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010055"},{"id":"00010057","register_sub_id":"101","register_pk":"196204","name":"辻本店表門及び塀","kana":"つじほんてんおもてもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字城外107他","lat":35.08608988,"lng":133.69095055,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"表門 木造、瓦葺、間口1.7m 塀 木造、瓦葺、総延長25m","structure_material":"表門 木造","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0262","desc":"奥座敷の式台玄関の西正面で、通り沿いに構えた表門と塀。表門は一間薬医門で、切妻造桟瓦葺とし、両開板扉を吊りこみ、破風に懸魚を飾る。左右に延びる塀は、真壁漆喰塗で桟瓦葺とし、腰部は外側が下見板張、内側は船板を竪張とする。街路景観を整える門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010057"},{"id":"00010053","register_sub_id":"101","register_pk":"196200","name":"辻本店事務所","kana":"つじほんてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷116","lat":35.08565498,"lng":133.69093349,"geo_status":"db","era":"江戸末期／昭和54改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積148㎡","structure_material":"土蔵造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0258","desc":"店舗の南に接続する土蔵造の建物で、切妻造桟瓦葺である。元は北から倉庫、醤油倉庫、納屋としていたが、二階床と間仕切の一部を撤去した。外壁は漆喰塗で腰を海鼠壁とする。西面一階の窓と出入口は後補で、元は店舗側から出入りした。街路の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010053"},{"id":"00010060","register_sub_id":"101","register_pk":"196207","name":"辻本店倉庫","kana":"つじほんてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字城外108-1","lat":35.08607415,"lng":133.69075893,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積223㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0265","desc":"西蔵の北に位置する土蔵造二階建で、通りに妻を見せた切妻造桟瓦葺とし、北に下屋を葺下ろす。下屋部分が古く、のちにこれを取込んで二階建を増築した。外壁は漆喰塗で軒裏を塗込め、腰を竪板張とし、東妻に水切二段を設ける。東面の戸口には瓦葺庇を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010060"},{"id":"00010052","register_sub_id":"101","register_pk":"196199","name":"辻本店店舗兼主屋","kana":"つじほんてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷116","lat":35.08579692,"lng":133.69099911,"geo_status":"db","era":"江戸後期／明治中期・昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積336㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0257","desc":"通りに西面して建つ造酒屋の店舗兼用住宅。切妻造桟瓦葺とし、北面東寄りに入母屋造の新座敷が取付く。正面に下屋を設け、一階に格子と出格子をたて、内部は中央土間の北を住居、南を店舗とする。二階壁の腰を海鼠壁とするなど当地に特徴的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010052"},{"id":"00010059","register_sub_id":"101","register_pk":"196206","name":"辻本店西蔵","kana":"つじほんてんにしぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字山本町屋敷112","lat":35.08580755,"lng":133.69070529,"geo_status":"db","era":"明治中期／平成10改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積136㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0264","desc":"主屋から通りを挟んだ向かい側に建つ土蔵造二階建で、切妻造桟瓦葺である。外壁は漆喰塗の大壁で軒裏を塗込めて水切を廻らし、腰、二階窓高と隅を海鼠壁とする。太い梁を何段にも重ねた豪壮な小屋組に醸造施設の往時を偲ばせる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010059"},{"id":"00010058","register_sub_id":"101","register_pk":"196205","name":"辻本店庭塀","kana":"つじほんてんにわべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県真庭市勝山字城外107他","lat":35.08615424,"lng":133.69121667,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、延長47m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0263","desc":"奥座敷東側の庭園の北面と東面を囲う塀で、通り側の塀の北端から矩折れに延びて東蔵に接続し、延長四七メートルを測る。コンクリート基礎上に建ち、真壁造漆喰塗で、腰を竪板張とする。東面塀はセメント瓦葺、北面塀は桟瓦葺で、東蔵への構内通路と庭を画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010058"},{"id":"00010056","register_sub_id":"101","register_pk":"196203","name":"辻本店社舎","kana":"つじほんてんやしろしゃ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県真庭市勝山字城外107","lat":35.08594929,"lng":133.69117467,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、銅板葺、建築面積0.2㎡","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0261","desc":"主屋新座敷の北、庭の南東寄りに位置する屋敷社である。一間社入母屋造の妻入で、唐破風向拝とも銅板葺とする。大石の上に鎮座し、円柱を長押で固め、組物は出組で中備蟇股とする。正側面に刎高欄付の縁を廻し、軒は二軒繁垂木である。本格的な造作の小社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010056"},{"id":"00000312","register_sub_id":"101","register_pk":"101302","name":"いろは丸展示館","kana":"いろはまるてんじかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県福山市鞆町鞆843-1、843-6","lat":34.38266648,"lng":133.38071064,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造2階建，瓦葺，建築面積211㎡","structure_material":"木造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"34 － 0010","desc":"鞆の船着場の正面に妻を見せて建つ２階建の土蔵。妻の中央と両脇をなまこ壁とし，腰に下見板を張り，窓の上に小庇を付ける等，正面の意匠はよく整っている。港に面したひときわ目立つ土蔵で，往事繁栄した鞆の様子を知ることができる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000312"},{"id":"00013652","register_sub_id":"101","register_pk":"505021","name":"太田家住宅主屋","kana":"おおたけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.43013889,"lng":132.74037222,"geo_status":"db","era":"明治38年頃／昭和4年改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積201㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0292","desc":"旧西国街道に南面する間口六間の二階建町家。入母屋造赤色桟瓦葺で正面に下屋を通し、背面に台所等の角屋を張出す。正面は東側が戸口で中央に平格子、西側は出格子を建て二階は黒タイル貼。内部は上手に仏間と座敷を並べる。街道の景観に寄与する重厚な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013652"},{"id":"00013656","register_sub_id":"101","register_pk":"505025","name":"太田家住宅北土蔵","kana":"おおたけじゅうたくきたどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.43042222,"lng":132.74039444,"geo_status":"db","era":"明治後期／昭和前期移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0296","desc":"敷地北東側に南北棟で建つ。土蔵造二階建、切妻造赤色桟瓦葺で南妻に戸口を開き、庇を設ける。周囲の階境に桟瓦葺の水切を廻らし、二階南妻の窓にも瓦庇を付す。小屋は、弓なりの梁に中引梁を渡して棟束を立てる。屋敷地後方の構えを形成する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013656"},{"id":"00013653","register_sub_id":"101","register_pk":"505022","name":"太田家住宅茶室棟","kana":"おおたけじゅうたくちゃしつとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.43032222,"lng":132.74022222,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0293","desc":"主屋と敷地北端の離れの間に建ち、渡廊下で繋ぐ。東西棟、入母屋造桟瓦葺の周囲に軽快に下屋を廻らす。六畳と北側の四畳半茶室からなり、両室とも数寄屋基調で西面に床を備える。茶室は網代天井で東端を掛込天井とする。風情ある庭空間を創る良質な茶室建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013653"},{"id":"00013654","register_sub_id":"101","register_pk":"505023","name":"太田家住宅離れ","kana":"おおたけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.43045278,"lng":132.74027222,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0294","desc":"敷地北西隅に東西棟で建つ入母屋造、赤色桟瓦葺で下屋を廻らす。庭を向く南面を開放的につくりガラス戸を建てる。内部は東の広い座敷と西の次の間からなり、座敷は大振りの床の左右に床脇と書院を造る。内外とも良材を用いて端正な意匠でまとめた離れ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013654"},{"id":"00013655","register_sub_id":"101","register_pk":"505024","name":"太田家住宅南土蔵","kana":"おおたけじゅうたくみなみどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.43020556,"lng":132.74045278,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0295","desc":"主屋北東に西国街道から後退して南北棟で建つ。土蔵造二階建、切妻造赤色桟瓦葺で西面を戸口とし、外壁漆喰塗で腰を海鼠壁とする。街道側の南妻は上下階に窓二個ずつ並べ、下階は梁間全長の、上階は窓毎に庇を付し、梁木口は漆喰塗小庇を付けて意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013655"},{"id":"00013657","register_sub_id":"101","register_pk":"505026","name":"太田家住宅門及び塀","kana":"おおたけじゅうたくもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条岡町778-4","lat":34.430525,"lng":132.74036667,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口1.8m、塀 木造、瓦葺、総延長33m","structure_material":"門 木造","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0297","desc":"敷地北面東寄りに開く門と、東西に折曲がりに廻る外塀及び門の西側から南にのびて通路と庭を画す内塀で、いずれも桟瓦葺。門は一間薬医門切妻造で両妻の女梁に絵様を施す。外塀は腰を竪板張とし、内塀は瀟洒な下地窓を飾る。屋敷構に趣を添える良質な門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013657"},{"id":"00013658","register_sub_id":"101","register_pk":"504605","name":"岡田家住宅主屋","kana":"おかだけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町910","lat":34.42960556,"lng":132.74695,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積212㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0298","desc":"市中心部にある酒問屋を営む商家。主屋は旧西国街道に北面して建つ入母屋造妻入で、正面下屋に幅広く出格子を建て、黒タイル貼の二階は両端に袖卯建を設ける。東を土間、西はミセ奥を二列四室とし、背後に角屋と風呂場を接続する。街道の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013658"},{"id":"00013659","register_sub_id":"101","register_pk":"504606","name":"岡田家住宅土蔵","kana":"おかだけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町910","lat":34.42940833,"lng":132.74694722,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0299","desc":"主屋の南側に西面して建つ。二階建の土蔵造桟瓦葺で、正面に入母屋屋根で格天井を張った一間幅の蔵前を付す。外壁は漆喰で軒先まで塗込め、腰をモルタル洗出しとする。内部は板敷で、壁は一階を竪板張、二階を漆喰塗とする。敷地中央の屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013659"},{"id":"00009829","register_sub_id":"101","register_pk":"195658","name":"株式会社日新林業加計出張所","kana":"かぶしきがいしゃにっしんりんぎょうかけしゅっちょうじょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県山県郡安芸太田町大字加計字神田3340","lat":34.60978922,"lng":132.32310448,"geo_status":"db","era":"大正10／昭和41改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"34 － 0138","desc":"街路に北面して建つ旧銀行店舗。木造平屋建であるが、正側面に庇をつけてつし二階建の町家風に見せる。屋根は寄棟造桟瓦葺で、軒を出桁造の塗籠とする。庇上の窓は内部では高窓となる。正面腰のタイル貼は後の改修であるが、側背面に旧の腰壁竪板張が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009829"},{"id":"00012643","register_sub_id":"101","register_pk":"367937","name":"旧片野製パン所","kana":"きゅうかたのせいぱんしょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県府中市上下町上下字翁1090-3","lat":34.698505,"lng":133.123383,"geo_status":"geocoded","era":"昭和9年／平成17年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び金属板葺、建築面積23㎡","structure_material":"木造平屋一部2階建","registered":"2018.11.02(平成30.11.02)","register_no":"34 － 0255","desc":"上下町本通り角地に東面して建つ平屋建で、角地側を二階建とする。一階を店舗、二階を床付の和室とし、外壁モルタル大壁の一階にアーチ窓、二階に縦長窓を並べる。柱形や軒蛇腹、開口頂部のレリーフなど豊かな装飾で、街道景観のアイストップとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012643"},{"id":"00010348","register_sub_id":"101","register_pk":"199121","name":"旧日の丸写真館","kana":"きゅうひのまるしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県竹原市本町1-4996-2","lat":34.345097,"lng":132.91079,"geo_status":"db","era":"昭和7年頃／昭和20年頃改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造3階建、瓦葺、建築面積97㎡","structure_material":"木造3階建","registered":"2014.12.19(平成26.12.19)","register_no":"34-0140","desc":"竹原市竹原伝建地区の南西、本川左岸の道路沿い角地に所在する台形敷地一杯に建ち、西角を隅切とした平面で、三階は北角も斜めにする。二階に写真修整室、三階に写場と現像室を設け、全体のかたちや開口部配置は当初を保持しており、特異な景観を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010348"},{"id":"00000093","register_sub_id":"101","register_pk":"101083","name":"旧マルヤマ商店事務所","kana":"きゅうまるやましょうてんじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県福山市松永町364-1","lat":34.45065921,"lng":133.26102954,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、建築面積90㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"34 － 0001","desc":"設計が長谷川建築事務所，施工が横山善吉と伝える事務所建築。装飾のあるパラペット，頭部に飾りがある１・２階を通した柱型，玄関ポーチ等に本格的な洋風の意匠がみられる。大正期に地域の技術者によって建てられた本格的洋風建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000093"},{"id":"00004416","register_sub_id":"101","register_pk":"105406","name":"恋しき主屋","kana":"こいしきしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県府中市府中町字横町564-1、字永井181-1","lat":34.57532817,"lng":133.23293221,"geo_status":"db","era":"明治初期／明治38・大正元増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階一部3階建、瓦葺、建築面積347㎡","structure_material":"木造2階一部3階建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0067","desc":"通り沿いの２階建，切妻造，平入が明治初期，背面に延びる３階建の客室が明治３８年，大正元年の増築になる。正面中央の望楼風３階も増築。格子や手摺などの細部には伝統的な意匠を残すが，変化に富んだ外観を構成し，街路景観上，際だった存在になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004416"},{"id":"00004417","register_sub_id":"101","register_pk":"105407","name":"恋しき離れ（桔梗の間）","kana":"こいしきはなれ（ききょうのま）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県府中市府中町字永井177","lat":34.57499931,"lng":133.23240534,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0068","desc":"敷地奥の中庭に北面して建つ。木造平屋建，東西棟の寄棟造，桟瓦葺で，銅板葺の庇を廻す。６畳の座敷と３畳の控室からなる。真壁造で，壁は黒漆喰仕上，丸窓，三日月窓など多彩な開口部を配し，格子を皮付材とするなど，野趣にも富んだ瀟洒な数寄屋風の建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004417"},{"id":"00004418","register_sub_id":"101","register_pk":"105408","name":"恋しき離れ（菊の間）","kana":"こいしきはなれ（きくのま）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県府中市府中町字永井178","lat":34.57484731,"lng":133.2326042,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0069","desc":"敷地奥の中庭に北面して建つ。真壁造，平屋建，東西棟の寄棟造，桟瓦葺で，６畳の座敷と３畳の控室からなり，廊下を延ばして手洗所を付属する。銘木を用いた床の間，木舞打の軒，櫛型風とした小壁の下地窓など，洗練された数寄屋風で，つくりも丁寧である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004418"},{"id":"00004419","register_sub_id":"101","register_pk":"105409","name":"恋しき離れ（桐・さつきの間）","kana":"こいしきはなれ（きり・さつきのま）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県府中市府中町字永井178、179-2","lat":34.57515545,"lng":133.23266838,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0070","desc":"主屋後方，中庭に面して建つ。真壁造，平屋建で，Ｌ字型棟とした入母屋造，桟瓦葺である。桐の間は６畳と８畳の２室構成，さつきの間は６畳１室で，東にある内玄関と廊下で連結する。書院造で，外壁黒漆喰塗で下屋庇を廻すなど，堂々とした外観構成をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004419"},{"id":"00004420","register_sub_id":"101","register_pk":"105410","name":"恋しき離れ（竹・萩の間）","kana":"こいしきはなれ（たけ・はぎのま）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"広島県","address":"広島県府中市府中町字永井179-5","lat":34.57497017,"lng":133.23279824,"geo_status":"db","era":"昭和23頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0071","desc":"敷地奥の中庭に西面して建つ。真壁造，平屋建，Ｌ字型棟とした切妻造，桟瓦葺で，４畳半茶室，８畳座敷，３畳控室などを巧みな平面構成で処理している。華奢な丸太柱，緩勾配の屋根や庇，竹や網代の造作，繊細な窓など，数寄屋風の軽快で風雅なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004420"},{"id":"00004414","register_sub_id":"101","register_pk":"105404","name":"竹村家主屋","kana":"たけむらやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市久保3-14-1","lat":34.40992075,"lng":133.20746283,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積481㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0065","desc":"木造２階建，桟瓦葺で，北が道路，南が海に面している。全体は南北棟の北側と東西棟の南側が直交したＴ字型の形態で，竹材の細工や造作を多用した繊細な書院造である。北正面は棟違いの八棟造風に扱うなど，外観は重厚かつ豪放で，地域景観の核になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004414"},{"id":"00004415","register_sub_id":"101","register_pk":"105405","name":"竹村家門及び塀","kana":"たけむらやもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市久保3-14-1","lat":34.41005812,"lng":133.20737133,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造、銅板葺、間口2.4m、板塀 木造、瓦葺、延長20m","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0066","desc":"門は北辺西寄りに設けられた切妻造，銅板葺の棟門で，簡素な矩折型の袖塀がつく。これに続く塀は，真壁造，桟瓦葺で，腰から上を黒漆喰塗とし，簾を入れた横長の小窓を開け，重厚さと繊細さを併せ持つ。敷地の北辺と西辺を区画しつつ，街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004415"},{"id":"00000418","register_sub_id":"101","register_pk":"101408","name":"田中写真館","kana":"たなかしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三次市吉舎町吉舎末政190他","lat":34.71965131,"lng":132.99123348,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造地上3階地下1階建，建築面積98㎡","structure_material":"木造地上3階地下1階建","registered":"1997.12.12(平成9.12.12)","register_no":"34 － 0014","desc":"木造３階建の写真館。むくり屋根を柱頭飾付きの円柱で受ける玄関部，ペディメントに設けたカイゼル髭をモチーフにした２連窓などを用いた特異な造形になる。設計施工は地元の棟梁吉川惣一。竣工時から話題となり，今も広く親しまれている建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000418"},{"id":"00012821","register_sub_id":"101","register_pk":"367724","name":"多門亭","kana":"たもんてい","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市東土堂町156-2","lat":34.40787,"lng":133.19808194,"geo_status":"db","era":"大正9年頃／昭和40年頃改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"34 － 260","desc":"千光寺山南腹にある旧料亭。切妻造桟瓦葺の総二階建で軒桁を丸桁、垂木を丸太とするなど素朴な数寄屋風に仕上げる。内部は上下階に各玄関を設け、一階に中廊下を通して小座敷を並べ、二階に大座敷を配する。山腹に広がる市街地の歴史的景観の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012821"},{"id":"00010512","register_sub_id":"101","register_pk":"199453","name":"西山本館","kana":"にしやまほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県尾道市十四日元町562他","lat":34.409629,"lng":133.20367,"geo_status":"db","era":"大正後期／昭和27改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階一部3階建、瓦葺、建築面積425㎡","structure_material":"木造2階一部3階建","registered":"2015.03.26(平成27.03.26)","register_no":"34 － 0147","desc":"旧出雲街道に面して建つ尾道港の旅館建築。木造二階建と三階建の棟が複雑に組み合わされ、すべての客室が庭に面するよう工夫される。丁寧な仕上げの数寄屋風の和室のほか、外国人船員の宿泊にも対応するよう洋室三室を持つなど、港町の風情を醸す木造旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010512"},{"id":"00009828","register_sub_id":"101","register_pk":"195657","name":"みはらし亭","kana":"みはらしてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県尾道市東土堂町甲150-2","lat":34.41011859,"lng":133.19910511,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積92㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"34 － 0137","desc":"千光寺山東方斜面の参道に面する木造二階建。高い石垣の上に建ち、東面に縁を設けて尾道水道の眺望を得る。二階北端に一二畳の主座敷を設け、南端の室は敷地形状により上下階とも変形平面を呈する。屋根は入母屋造桟瓦葺で、軒は丸太の化粧垂木を隅扇に配る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009828"},{"id":"00000171","register_sub_id":"101","register_pk":"101161","name":"三次市歴史民俗資料館（旧三次銀行）","kana":"みよししれきしみんぞくしりょうかん（きゅうみよしぎんこう）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三次市三次町1236","lat":34.81099187,"lng":132.84797427,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積190㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"34 － 0007","desc":"当初銀行の社屋として建てられ、現在では公有化され資料館として利用されている。入口正面のカウンター奥に窓口事務室が広がり、２階部分をバルコニーの付いた吹き抜けとしている。簡素ではあるが柱頭飾りなどのアクセントのある外観で親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000171"},{"id":"00013322","register_sub_id":"101","register_pk":"366311","name":"向酒店店舗兼主屋","kana":"むかいさけてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市久保一丁目682","lat":34.40964444,"lng":133.20465,"geo_status":"db","era":"大正14年頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造二階建、瓦葺、建築面積77㎡","structure_material":"木造二階建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0264","desc":"尾道市街地に建つ店舗兼用住宅。一階正面を土間のミセ、二階は座敷とする。二階正面を漆喰で塗籠め、袖壁を設ける。大屋根は桟瓦葺だが、一階正面の庇を本瓦葺として重厚に見せる一方、二階の建ちは高い近代の町家の特徴を持つ。港町尾道の景観の一部を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013322"},{"id":"00009833","register_sub_id":"101","register_pk":"195662","name":"旧宮崎商館","kana":"きゅうみやざきしょうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県下関市田中町2-15","lat":33.95893709,"lng":130.94169459,"geo_status":"db","era":"明治40／昭和中期・平成20改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"煉瓦造2階建、銅板葺、建築面積197㎡","structure_material":"煉瓦造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0077","desc":"街路に南面する煉瓦造二階建。正面中央の玄関アーチは迫元と要石の間に迫石を挟む。左右の窓枠は、切石の楣と窓台を延ばした水平帯で立面を引き締める。二階ヴェランダは要石を入れた五連アーチとし、軒先をデンティルで飾る。整った意匠になる煉瓦造の商館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009833"},{"id":"00001532","register_sub_id":"101","register_pk":"102522","name":"國安家住宅","kana":"くにやすけじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"山口県","address":"山口県岩国市岩国1-7-3","lat":34.16619673,"lng":132.17915538,"geo_status":"db","era":"嘉永3前","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造2階建、瓦葺、建築面積257㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"35 － 0032","desc":"岩国の有力商家が集まる本町筋に立地する元鬢付油製造販売業「松金屋」の主屋。間口９間規模のつし２階，平入，塗屋造の町屋建築で，つし２階正面にあけられた横格子の虫籠窓に特徴があり，江戸時代の岩国城下町の様子を伝える商家建築として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001532"},{"id":"00009537","register_sub_id":"101","register_pk":"194330","name":"玉椿旅館","kana":"たまつばきりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県下関市豊浦町大字川棚字湯町5132","lat":34.13816037,"lng":130.9383557,"geo_status":"db","era":"大正10年頃／昭和後期改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積696㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"35 － 0073","desc":"川棚温泉の温泉旅館。敷地東側の木造二階建大広間の北西に厨房と客室、西に浴室、別棟座敷等が接続する。大相撲で横綱が出る度に増築を重ねたといい複雑な平面をもつ。大広間は二階の四〇畳二室の続き間で北端に舞台、南端にトコを構え、折上格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009537"},{"id":"00014956","register_sub_id":"101","register_pk":"519216","name":"中野家住宅衣装蔵","kana":"なかのけじゅうたくいしょうぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.386975,"lng":131.10043611,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0118","desc":"敷地西辺の北寄りに建つ衣装蔵。二階建切妻造平入桟瓦葺の南北棟。外壁は軒まで塗込め漆喰塗仕上とし腰に水切瓦を廻らす。東面に二箇所の石段付の戸口を設けて庇を付す。内部は各階一室の板敷で中央に階段を配す。米蔵と並び建ち、敷地北西の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014956"},{"id":"00014951","register_sub_id":"101","register_pk":"519211","name":"中野家住宅内蔵","kana":"なかのけじゅうたくうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.3868,"lng":131.10058056,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0113","desc":"主屋に北隣し、商品や家財道具を収納する土蔵。二階建切妻造平入の南北棟で東面南寄りに戸口を設け廊下で主屋と接続する。外壁は軒裏まで漆喰で塗込め、二階東に窓を二箇所開け、庇を付す。内部は各階一室の板敷。重厚な外観が敷地中央の景観をつくる内蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014951"},{"id":"00014954","register_sub_id":"101","register_pk":"519214","name":"中野家住宅穀物蔵","kana":"なかのけじゅうたくこくもつぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.38679722,"lng":131.10050278,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0116","desc":"主屋北西に位置する穀物蔵。二階建切妻造桟瓦葺の南北棟。東面北寄りと南面中央に戸口を設け、2階東面に1箇所窓を開ける。外壁は漆喰塗仕上で腰は石張。各階は板敷で南北２室に仕切り、北室１階中央上部を吹抜とする。主屋とともに敷地内の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014954"},{"id":"00014955","register_sub_id":"101","register_pk":"519215","name":"中野家住宅米蔵","kana":"なかのけじゅうたくこめぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.38688611,"lng":131.10045556,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積52㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0117","desc":"敷地西辺中央北寄りに建つ米蔵。平屋建切妻造平入桟瓦葺の南北棟。外壁は軒まで漆喰で塗込め、東面に二箇所の石段付の戸口を設けて庇を付す。西と東の中央に各一箇所窓を開ける。内部各階一室の板敷で壁は縦板張。北に衣装蔵が並び、敷地北西の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014955"},{"id":"00014953","register_sub_id":"101","register_pk":"519213","name":"中野家住宅茶室","kana":"なかのけじゅうたくちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.38703889,"lng":131.10063333,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0115","desc":"離れの北東に位置する四畳半の茶室。入母屋造桟瓦葺の南北棟で東南の軒先を銅板葺とする。内部は北に床と棚、西に火灯窓、東と南に障子と雨戸を建て、欄間に下地窓を開き、濡縁を廻らす。床廻りに銘木用いて意匠を凝らし、庭に面し開放的なつくりとした茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014953"},{"id":"00014950","register_sub_id":"101","register_pk":"519210","name":"中野家住宅店舗兼主屋","kana":"なかのけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.38670278,"lng":131.10059722,"geo_status":"db","era":"明治中期／昭和22年頃・平成5年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積244㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0112","desc":"赤間関街道の古市にある呉服商の店舗兼主屋。通りに南面する２階建切妻造桟瓦葺で外壁は漆喰塗で仕上げる。内部北半は床上、南半は広い土間とし、上部吹抜周囲に廊下を廻らし、洋品店時の陳列棚を並べる。間口長大で、街道沿いの歴史的な景観の核となる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014950"},{"id":"00014952","register_sub_id":"101","register_pk":"519212","name":"中野家住宅離れ","kana":"なかのけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県長門市日置上字下市6057他","lat":34.38693333,"lng":131.10058611,"geo_status":"db","era":"大正後期／昭和4年頃増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建一部3階建、瓦葺、建築面積171㎡","structure_material":"木造平屋建一部3階建","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0114","desc":"主屋の北に位置する賓客用の座敷棟。平屋建桟瓦葺で南に切妻造の玄関を付し、北西に三階建で外壁を下見板張とした洋風望楼が建つ。４室の座敷周囲に廊下を廻らし、望楼一階の化粧間は扇状に竿縁天井を張る凝った意匠。洋風望楼が地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014952"},{"id":"00014957","register_sub_id":"101","register_pk":"519217","name":"中野家住宅門及び塀","kana":"なかのけじゅうたくもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県長門市日置上字下市6057","lat":34.38678333,"lng":131.10070278,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"門 木造、瓦葺、間口1.6m 塀 木造、瓦葺、総延長36m","structure_material":"門 木造","registered":"2024.03.06(令和6.03.06)","register_no":"35 - 0119","desc":"敷地東辺に沿って建つ門及び塀。門は一間一戸の薬医門で、主柱と控柱間に架けた梁上に束を立てて棟木を支持し、軒は一軒疎垂木とする。門の南北に延びる塀は腰高に積んだ石積上に建ち、屋根は桟瓦葺。簡素な門ながら塀と一体となって敷地東辺の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014957"},{"id":"00002094","register_sub_id":"101","register_pk":"103084","name":"柳井市町並み資料館（旧周防銀行本店）","kana":"やないしまちなみしりょうかん（きゅうすおうぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県柳井市大字柳井津字金屋町442","lat":33.96930931,"lng":132.10961907,"geo_status":"db","era":"明治40／平成12移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積174㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"35 － 0039","desc":"柳井市伝建地区の入口近くに所在。日本銀行技師の長野宇平治の原設計，佐藤節雄の実施設計による銀行建築。長野宇平治が古典主義様式を確立する以前の作品で，正面階下のムクリ状のアーチや薄く張り出したバルコニーなどに様式的な試行錯誤の跡が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002094"},{"id":"00015245","register_sub_id":"101","register_pk":"530669","name":"料亭高大大広間","kana":"りょうていたかだいおおひろま","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県萩市大字唐樋町字唐樋町83他","lat":34.410425,"lng":131.40184167,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積305㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0122","desc":"敷地西端に建つ寄棟造桟瓦葺の大広間。六〇畳と四〇畳の二室からなり、西面に床、両床脇、付書院、東面に舞台を構え、南面は濡縁、北面は内縁を通す。床は上壇を構え、床柱は太いサクラの皮付丸太。トラスを用いて実現した大空間に合わせた意匠の料亭大広間。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015245"},{"id":"00015244","register_sub_id":"101","register_pk":"530668","name":"料亭高大玄関及び廊下","kana":"りょうていたかだいげんかんおよびろうか","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県萩市大字唐樋町字唐樋町83他","lat":34.41043611,"lng":131.40208611,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積153㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0121","desc":"旧萩往還沿いに位置する料亭旅館。玄関は、敷地中央に東面して建つ、入母屋造桟瓦葺で正面に二間幅の式台を構える。玄関と大広間を繋ぐ廊下は、両下造桟瓦葺、一間半幅の畳敷で北西に配膳室を接続する。玄関は頭貫上に彫刻付蟇股を掲げ、料亭の風格を演出。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015244"},{"id":"00015246","register_sub_id":"101","register_pk":"530670","name":"料亭高大土蔵","kana":"りょうていたかだいどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県萩市大字唐樋町字唐樋町83他","lat":34.41041111,"lng":131.40194167,"geo_status":"db","era":"明治前期／昭和51年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土造2階建、瓦葺、建築面積58㎡","structure_material":"土造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0123","desc":"玄関北隣に建つ食器や膳の収納蔵。二階建切妻造桟瓦葺の東西棟で西面に戸口を開ける。外壁は縦羽目板張で軒廻りは漆喰塗込。内部は各階一室で一階は厨房、二階は板敷の収納蔵とし、登梁の和小屋の棟通りに棚を設える。玄関と一体で敷地中央の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015246"},{"id":"00005506","register_sub_id":"101","register_pk":"106494","name":"織本屋（旧折目家住宅）主屋","kana":"おりもとや（きゅうおりめけじゅうたく）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字町83-2","lat":34.03347197,"lng":134.0627272,"geo_status":"db","era":"明和9","year":1772,"year_source":"db","year_min":1772,"year_max":1772,"year_label":null,"structure":"木造2階建、瓦葺、建築面積276㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"36 － 0060","desc":"南北に通る街道に東を正面として建つ商家建築で，古い部分は棟札から年代が判る。切妻造，平入の２階建で，正面に下屋を設ける。本瓦葺の屋根や漆喰塗の外壁など全体に重厚感があり，両側面のうだつは斜めの下段と水平の上段からなる古い形式が特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005506"},{"id":"00012992","register_sub_id":"101","register_pk":"368070","name":"河井百貨店","kana":"かわいひゃっかてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県三好市東祖谷京上146-7","lat":33.86818333,"lng":133.90448611,"geo_status":"db","era":"昭和9年／昭和中期増築、昭和40年代改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、金属板葺、建築面積129㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"36 － 197","desc":"東祖谷中心部のもと日用雑貨店。街道に南面して建つ入母屋造鉄板葺の二階建で、西側に別棟を接続する。1階を全面土間の店とし、2階に3室を並べて南東二面に縁を廻す。建ちが高く、間口の広い大型町家で、街道沿いの歴史的景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012992"},{"id":"00012989","register_sub_id":"101","register_pk":"368068","name":"喜多薬店","kana":"きたやくてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県三好市西祖谷山村一宇277","lat":33.89246389,"lng":133.81642222,"geo_status":"db","era":"昭和15年頃／昭和30年頃増築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階地下1階建、瓦葺、建築面積143㎡","structure_material":"木造2階地下1階建","registered":"2019.09.10(令和1.09.10)","register_no":"36 － 194","desc":"西祖谷中心部の日用雑貨店。街道に東面して建つ切妻造セメント瓦葺の二階建で、北を落棟とする。1階前方を前土間の店とし、後方に3室を並べ、2階に2列4室を配し、祖谷川に面する西側を懸造状にして地階を設ける。街道沿いの歴史的町並みを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012989"},{"id":"00014681","register_sub_id":"101","register_pk":"515223","name":"旧四国銀行辻支店車庫","kana":"きゅうしこくぎんこうつじしてんしゃこ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"徳島県","address":"徳島県三好市井川町辻88-2","lat":34.0294,"lng":133.88010278,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"36 - 0223","desc":"銀行店舗の背面に位置する自動二輪車庫。鉄板葺片流れ屋根の平屋建、外壁はモルタル塗リシン吹付仕上、正面に小庇を付し、引違板戸を立てる。内部は大小２室の土間で、大きい北室を車庫、南室を倉庫とする。形式は簡素だが、当時の銀行営業の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014681"},{"id":"00014680","register_sub_id":"101","register_pk":"515222","name":"旧四国銀行辻支店店舗","kana":"きゅうしこくぎんこうつじしてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"徳島県","address":"徳島県三好市井川町辻88-2","lat":34.0293,"lng":133.88025556,"geo_status":"db","era":"昭和34年／昭和後期改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造、建築面積149㎡","structure_material":"鉄筋コンクリート造","registered":"2023.08.07(令和5.08.07)","register_no":"36 - 0222","desc":"辻地区中心部の伊予街道に面する銀行店舗。鉄筋コンクリート造二階建、外部はモルタル洗出に目地切り石張風仕上とし、玄関柱形が正面性を高める。表側の営業室は元は吹抜で二階に回廊を巡らす。背面側は中廊下型平面で諸室を並べる。地域の近代化を象徴する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014680"},{"id":"00008583","register_sub_id":"101","register_pk":"134979","name":"近藤家住宅主屋","kana":"こんどうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県鳴門市大麻町板東字北条86-1","lat":34.15669411,"lng":134.50225303,"geo_status":"db","era":"明治中期／昭和26年・昭和30年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0086","desc":"四国霊場霊山寺の門前、参道と撫養街道の角に東西棟で建つ。入母屋造本瓦葺で、四方に下屋を付設するが、北と東で軒高を違え変化を付ける。間口一二メートル奥行八・一メートルの木造つし二階建で、上屋を大壁とし、軒まで塗り込めるなど、重厚な構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008583"},{"id":"00012048","register_sub_id":"101","register_pk":"210989","name":"島尾家住宅店舗兼主屋","kana":"しまおけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市井川町辻85-1","lat":34.029037,"lng":133.879969,"geo_status":"db","era":"明治10年頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積175㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-168","desc":"井川町辻の中心地、街路に南面して建つ。木造二階建、切妻造本瓦葺で、奥行南北に細長い平面に、緩やかな平入屋根をかける。表側に店舗部分を取り、右側に土間を通して背面側に作業場を設ける。二階はほぼ正方形の平面とする。町並景観に寄与する町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012048"},{"id":"00010690","register_sub_id":"101","register_pk":"201264","name":"炭米穀店店舗兼主屋","kana":"すみべいこくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県鳴門市撫養町南浜字蛭子前東41","lat":34.174753,"lng":134.603348,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積164㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"36－0126","desc":"通り沿いに建つ、米穀店の店舗兼用住宅。木造二階建で屋根を本瓦葺とし、正面の上下階とも出格子を配する。内部は一階前面を広いミセとし、東寄りに二室続きの座敷を並べて座敷飾を設え、東の庭側に廊下を付す。四国の玄関口としての賑わいを伝える商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010690"},{"id":"00012047","register_sub_id":"101","register_pk":"210988","name":"大正館店舗兼主屋","kana":"たいしょうかんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県小松島市小松島町字外開7-11","lat":34.009886,"lng":134.586412,"geo_status":"db","era":"大正7年／平成18年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"36-167","desc":"小松島市中心市街地にあり北面する町家。間口六間半で中央に通り土間を通し、西半をミセや旧倉庫とし、東半に帳場やオモテなど四室を配する。二階には平書院を備えた上質な座敷飾りを備える。正面の出格子や二階の手摺など港町の歴史的景観をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012047"},{"id":"00000271","register_sub_id":"101","register_pk":"101261","name":"高原ビル","kana":"たかはらびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県徳島市東船場町1-13","lat":34.0703172,"lng":134.54888446,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建，建築面積87㎡","structure_material":"鉄筋コンクリート造3階建","registered":"1997.07.15(平成9.07.15)","register_no":"36 － 0007","desc":"通りに面して建つＲＣ造のビル。一部を塔屋風に３階建てとし，他は２階建てとする。スクラッチタイルの外壁，パラペットの装飾，塔屋風の部分の窓廻りの装飾等に特徴がある。昭和初期の都市部における洋風の意匠を持つ小規模なビルの好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000271"},{"id":"00012654","register_sub_id":"101","register_pk":"367948","name":"古本家住宅店舗兼主屋","kana":"ふるもとけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町佐野金氏935-1","lat":34.003742,"lng":133.703568,"geo_status":"geocoded","era":"明治25年頃／明治後期移築","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積261㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"36 － 0187","desc":"市西部の山村にある地主宅で、主屋は街道沿いに南面して建つ。店舗とする東側が切妻造、居室とする西側が入母屋造で、下屋を廻し、中央部に玄関を構える。上手に瀟洒な座敷飾の座敷と前室を並べ、正側面に縁を設ける。山村の地主層の暮らしを伝える大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012654"},{"id":"00012655","register_sub_id":"101","register_pk":"367949","name":"古本家住宅土蔵","kana":"ふるもとけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県三好市池田町佐野金氏935-1","lat":34.003742,"lng":133.703568,"geo_status":"geocoded","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"36 － 0188","desc":"敷地南西隅の街道沿いに建つ。土蔵造二階建、切妻造で、北面に吹放し下屋を付す。外壁は下部縦板張、中間下見板張、上部漆喰塗で鉢巻を廻し、上下階南面に各二窓を開く。内部は東西に二分し、北東二面に戸口を設ける。街道の歴史的景観を形成する大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012655"},{"id":"00012656","register_sub_id":"101","register_pk":"367950","name":"古本家住宅庭門及び塀","kana":"ふるもとけじゅうたくにわもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県三好市池田町佐野金氏935-1","lat":34.003742,"lng":133.703568,"geo_status":"geocoded","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"庭門 木造、瓦葺、間口2.0m、北方袖塀付 塀 木造、瓦葺、延長15m","structure_material":"庭門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"36 － 0189","desc":"主屋玄関東側に取付き、東面して建つ一間腕木門と、門南端から矩折れに延びて土蔵東南隅に至る塀。塀は壁漆喰塗の腰縦板張で、一間おきに下地窓を穿つ。出隅部屋根には阿波踊の踊子を表した留蓋瓦を載せる。主屋前庭を囲み、風格ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012656"},{"id":"00012653","register_sub_id":"101","register_pk":"367947","name":"前田商店店舗兼主屋","kana":"まえだしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県三好市東祖谷久保727-9他","lat":33.85648,"lng":133.960327,"geo_status":"geocoded","era":"昭和20年頃","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"36 － 0186","desc":"市南端部の山中の街道沿いに西面して建つ商家主屋。総二階建の正面北端に入母屋玄関を出し、北側に平屋の居室部が取付く。一階に長大材の架構による広い店舗、二階に座敷を設け、正面廊下の欄間を扇面形の下地窓で飾る。山間集落の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012653"},{"id":"00010693","register_sub_id":"101","register_pk":"201267","name":"村田旅館蔵","kana":"むらたりょかんくら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県吉野川市美郷字古土地131-4","lat":34.031884,"lng":134.298892,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"36－0129","desc":"本館から客室棟を挟んで背後の西方に建つ。土蔵造二階建で、桁行五・七メートル梁間四・三メートルである。小屋組は登梁形式とし、二階内法が比較的高い。東正面一階には腕木を出して庇を設ける。敷地形状を利用し、背後の川と相まって、歴史的景観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010693"},{"id":"00010692","register_sub_id":"101","register_pk":"201266","name":"村田旅館本館","kana":"むらたりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県吉野川市美郷字古土地134-2","lat":34.03172,"lng":134.29904,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"36－0128","desc":"四国山地の山間部に位置する店舗兼旅館。一階に店舗、二階に客室用の座敷を配し、二階は敷地の高低差のため、背面側から直接に出入りができるようになっている。座敷は八畳と六畳からなり、外廻りに高欄をまわすなど山間地における旅館の風情を醸している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010692"},{"id":"00008582","register_sub_id":"101","register_pk":"134978","name":"和田の屋本館下棟","kana":"わだのやほんかんしもとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"徳島県","address":"徳島県徳島市眉山町大滝山5-5他","lat":34.0723895,"lng":134.54267135,"geo_status":"db","era":"昭和28年／昭和31年増築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0085","desc":"大滝山山麓、登り口に北面する。東西一三メートル南北五・六メートル、西面に増築部を付設。東西棟を主棟とし、東端に南北棟の入母屋屋根を造るなど複雑な屋根とする。一階は土間で、餅の焼き場や販売所、二階に座敷を設ける。観光地に残る老舗店舗の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008582"},{"id":"00004828","register_sub_id":"101","register_pk":"105818","name":"愛染家住宅主屋","kana":"あいぜんけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市東ハゼ町897","lat":34.322914,"lng":134.04031826,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"37 － 0273","desc":"街道に東面する敷地に建つ。全体はコ字平面で，表屋は南北棟，入母屋造，桟瓦葺の２階建町家で，正面に下屋を出し，中央北寄りに入母屋造玄関を設ける。２階外壁は黒漆喰塗で，腰に白タイルを張り，軒は段形に銅板で覆うなど重厚にして瀟洒な表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004828"},{"id":"00004831","register_sub_id":"101","register_pk":"105821","name":"愛染家住宅西蔵","kana":"あいぜんけじゅうたくにしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県高松市東ハゼ町897","lat":34.322929,"lng":134.040222,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"37 － 0276","desc":"主屋の南方，東蔵の西方に位置し，南北棟で建つ。桁行５間梁間２間半規模，切妻造，桟瓦葺，平入の２階建土蔵で，東面の北端に庇を差し掛けて戸口を設ける。もと酒瓶詰蔵で，外部は腰海鼠壁，上部白漆喰塗，軒鉢巻き付きで東蔵と同様なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004831"},{"id":"00004830","register_sub_id":"101","register_pk":"105820","name":"愛染家住宅東蔵","kana":"あいぜんけじゅうたくひがしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県高松市東ハゼ町897","lat":34.32283204,"lng":134.04026041,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"37 － 0275","desc":"主屋の南方に位置し，東西棟で建つ。桁行３間梁間２間，切妻造，桟瓦葺，平入の２階建土蔵で，北面の東端に庇を付けて戸口を設ける。もと酒保管蔵で，外部は腰高の海鼠壁とし，上部は白漆喰塗，軒には鉢巻きを廻す。金比羅街道に面した表構えの構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004830"},{"id":"00008072","register_sub_id":"101","register_pk":"128903","name":"泉家住宅主屋","kana":"いずみけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田字畑方2244-1他","lat":34.22665138,"lng":134.40418982,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"37-0338","desc":"旧街道に西面して建つ。切妻造本瓦葺で、正・背面に下屋庇を付ける。間口１１ｍ奥行８．８ｍの木造つし２階建。上屋は漆喰塗で、出桁まで塗り込め、虫籠窓を開け、下屋には出格子を残す。南寄りにニワ、北側に田の字型に床上を配する。商家の表構えをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008072"},{"id":"00003613","register_sub_id":"101","register_pk":"104603","name":"かめびし圧搾場","kana":"かめびしあっさくば","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2132","lat":34.22869669,"lng":134.40311724,"geo_status":"db","era":"明治初期／昭和初期改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0170","desc":"主屋（事務室・展示室）の西方，道路を隔てた西敷地に主屋と向き合って建つ。もとは問屋業を営む他家の主屋。桁行１２．３ｍ梁間７．２ｍ規模，切妻造，本瓦葺のつし２階建で，東面は改造されているが，西面は商家主屋の面影をよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003613"},{"id":"00003615","register_sub_id":"101","register_pk":"104605","name":"かめびし旧四号蔵及び旧六号蔵","kana":"かめびしきゅうよんごうぐらおよびきゅうろくごうぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2132","lat":34.22873545,"lng":134.40291448,"geo_status":"db","era":"明治初期／大正末期増改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積153㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0172","desc":"西敷地北辺中央に位置する旧六号蔵は桁行１２ｍ梁間６ｍ規模で，南方矩折れに旧四号蔵がつながる。旧四号蔵は桁行１３．４ｍ梁間６ｍ規模，南北棟，切妻造，本瓦葺の平屋建で，軒先低く屋根を葺き下ろす。貯蔵用倉庫であるが，もとは問屋の施設とみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003615"},{"id":"00003600","register_sub_id":"101","register_pk":"104590","name":"かめびし事務室及び展示室","kana":"かめびしじむしつおよびてんじしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22860152,"lng":134.40328214,"geo_status":"db","era":"安永9／江戸末期増築","year":1780,"year_source":"db","year_min":1780,"year_max":1780,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積372㎡","structure_material":"木造2階一部平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0157","desc":"引田の中心的街路に西面して建つ。もとの主屋で，主体部は間口１９ｍ規模，入母屋造，本瓦葺のつし２階建とし，北東に釜屋を角屋状に張り出し，南方に座敷を増築している。近年施設全般をべんがら色基調に統一し，独特の景観をつくりだして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003600"},{"id":"00004656","register_sub_id":"101","register_pk":"105646","name":"キッコ石石井家内浜長屋","kana":"きっこいしいしいけうちはまながや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜881-10","lat":34.47458765,"lng":134.31883697,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積185㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0248","desc":"醤油醸造主が市街中心部に建設した貸商店長屋。間口３間規模の貸店舗を６軒連ねて道路に西面して建ち，全体を南北棟，入母屋造，桟瓦葺の木造２階建につくり，背面各戸に便所等を角屋状に突出させる。醤油醸造で栄えた街の発展を物語る建物として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004656"},{"id":"00004026","register_sub_id":"101","register_pk":"105016","name":"香龍北川家住宅主屋","kana":"こうりゅうきたがわけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市円座町字永井979-1","lat":34.28897858,"lng":134.01398373,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0191","desc":"高松市街南方，香東川に架かる円座橋西詰近くに位置し，遍路道に南面して建つ。平面規模は桁行９間半梁行５間半，入母屋造，桟瓦葺のつし２階建で，２階は黒漆喰で塗込め，正面に虫籠窓を配す。４隅に施された白漆喰塗の隅柱彫刻が地域の目印となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004026"},{"id":"00003329","register_sub_id":"101","register_pk":"104319","name":"こんぴらうどん参道店（旧櫻屋旅館）","kana":"こんぴらうどんさんどうてん（きゅうさくらやりょかん）","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡琴平町字川西810-3","lat":34.187019,"lng":133.817917,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0156","desc":"南と東が街路に面した角地にあり，南を正面とした平入の木造・２階建で，桟瓦葺屋根は東が入母屋造，西が切妻造になる。料理店に改装されたが，草花彫刻をつけた２階高欄など旅館建築らしい細部を残し，金刀比羅宮の東の参道景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003329"},{"id":"00005922","register_sub_id":"101","register_pk":"106907","name":"重元果物店店舗","kana":"しげもとくだものてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県丸亀市浜町115-2","lat":34.29211005,"lng":133.79420991,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"37 － 0308","desc":"桁行６間，梁間３間，木造２階建，入母屋造，本瓦葺の商店街に面した町家建築である。２階外壁は黒漆喰塗と黒色タイル貼で仕上げる。香川県内では，丸亀と多度津の市街地で限定的にみられる手法で，地域色のある建築意匠の遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005922"},{"id":"00001139","register_sub_id":"101","register_pk":"102129","name":"下高瀬簡易郵便局（旧丸岡呉服店）","kana":"しもたかせかんいゆうびんきょく（きゅうまるおかごふくてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県三豊市三野町下高瀬字乙井533-2","lat":34.20169775,"lng":133.7057428,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造２階建，瓦葺，建築面積225㎡","structure_material":"木造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0019","desc":"呉服店の店舗として建てられた。京都の近代建築を模してつくったと伝える通り，周辺の民家よりはるかに規模が大きいひときわ目立つ洋風建築である。内部中央に吹き抜けのギャラリーがあり，その上部に天窓を設けるなど空間構成にもみどころがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001139"},{"id":"00002692","register_sub_id":"101","register_pk":"103682","name":"瀬川酒店主屋","kana":"せがわさけてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県善通寺市上吉田町1-4-10","lat":34.229134,"lng":133.786575,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0090","desc":"善通寺市役所の向かい，ＪＲ善通寺駅から西方に延びる駅前通りに南面して建つ。間口８間ほどの虫籠窓を開けたつし２階建の塗屋造店舗で，棟梁は音田定吉と伝える。長大な入母屋造の本瓦葺屋根を通り沿い見せ，「師団一」の銘柄とともに広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002692"},{"id":"00002826","register_sub_id":"101","register_pk":"103816","name":"瀬川酒店東蔵","kana":"せがわさけてんひがしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県善通寺市上吉田町1-4-10","lat":34.229279,"lng":133.786652,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積146㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0094","desc":"ＪＲ善通寺駅前から西に延びる通りに面して建つ。南北棟，桟瓦葺切妻造の酒蔵で，東西棟，平入の店舗主屋の東に接して建ち，南妻面を通りに見せる。南面は腰を海鼠壁として意匠を整え，店舗主屋とともに老舗の店構えと佇まいを今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002826"},{"id":"00003322","register_sub_id":"101","register_pk":"104312","name":"天満屋呉服店主屋","kana":"てんまんやごふくてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市仏生山町字桜馬場甲542","lat":34.280247,"lng":134.047775,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積177㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0149","desc":"法然寺に向かう街道の東側にある。西を正面とした木造・２階建，平入で，南面切妻造，北面入母屋造の本瓦葺屋根をあげ，西と北に下屋庇を廻す。２階は大柄な虫籠窓を設け，北端の袖壁，南隅の持送りに鏝絵を施すなど，凝った細部を備えた門前町の商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003322"},{"id":"00004044","register_sub_id":"101","register_pk":"105034","name":"へんこつ屋店舗","kana":"へんこつやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡琴平町字川東240-2","lat":34.18848675,"lng":133.82033503,"geo_status":"db","era":"明治中期／昭和初期改造","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積136㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0209","desc":"金刀比羅宮参道筋一之橋東詰近く，新町西商店街に南面して東西棟で建ち，奥に棟を延ばす。角地に位置し，正面は南西の２面に下屋を取り付けた標準的な構えをとるが，内部には網代組のヴォールト状天井など，凝った造作や銘木珍木の使用が随所にみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004044"},{"id":"00012249","register_sub_id":"101","register_pk":"353050","name":"寳月堂南館","kana":"ほうげつどうみなみかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県丸亀市米屋町14-2他","lat":34.291949,"lng":133.797182,"geo_status":"db","era":"大正7年／昭和6年増築、昭和32年・同41年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積216㎡","structure_material":"木造2階一部3階建","registered":"2018.03.27(平成30.03.27)","register_no":"37-431","desc":"丸亀市中心部に建つ。外観は北半部を釉薬タイル貼にスパニッシュ瓦の洋風、南半部を平入黒漆喰塗町家風にまとめる。内部は暖炉を設け腰板張の洋風意匠の洋室や、和風の座敷、茶室を収め複雑な様相を示す。様々な要素を織り交ぜた昭和初期の商店建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012249"},{"id":"00008071","register_sub_id":"101","register_pk":"128902","name":"松村家住宅主屋","kana":"まつむらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田字畑方2243","lat":34.22677278,"lng":134.40413155,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積198㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"37 - 0337","desc":"旧街道に西面して建つ。間口１８ｍのつし２階建、入母屋造本瓦葺で、正面に下屋庇を設ける。上屋には虫籠窓を開け、出桁まで塗り込め、正面北寄りには出格子を残す。内部は中央にゲンカン、南にミセ、北にザシキなどを配す。旧街道筋の歴史的景観を伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008071"},{"id":"00005038","register_sub_id":"101","register_pk":"106028","name":"丸尾醸造所西主屋","kana":"まるおじょうぞうしょにししゅおく","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県仲多度郡琴平町榎井字籏岡94","lat":34.19048103,"lng":133.82866917,"geo_status":"db","era":"明治中期／昭和12増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積103㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0284","desc":"東主屋の西に並び建つ。間口４間，東西棟，切妻造，桟瓦葺，平入の２階建で，背面の庭園に面して８畳仏間と８畳座敷を有する南北棟の座敷棟と便所棟を増築する。東主屋よりたちの高い２階建で，東中商店街の歴史的景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005038"},{"id":"00005037","register_sub_id":"101","register_pk":"106027","name":"丸尾醸造所東主屋","kana":"まるおじょうぞうしょひがししゅおく","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県仲多度郡琴平町榎井字籏岡94","lat":34.19173255,"lng":133.82888555,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"塗屋造2階建、瓦葺、建築面積155㎡","structure_material":"塗屋造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0283","desc":"東中商店街に北面して建つ。間口７間，切妻造，桟瓦葺，平入の２階建町家で，北面に庇を付け，東方を店舗，西方を事務室として使用。２階正面は黒漆喰塗で，白縁取の縦格子虫籠窓２所を並べる。琴平への入口にあたる街道筋の歴史的景観をかたちづくる要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005037"},{"id":"00001754","register_sub_id":"101","register_pk":"102744","name":"水尾写真館","kana":"みずおしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県善通寺市上吉田町3-4-6","lat":34.22693366,"lng":133.78137525,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積426㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0054","desc":"善通寺駅前通りに面して南面して建つ。木造２階建、下見板張りの写真館で、道路沿い正面の２階中央上部を立ち上げてゲーブルをつくり、館名を入れる。正面道路側を店舗とし、奥にスタジオを設ける。凹凸の少ないグラフィカルなファサード構成に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001754"},{"id":"00004032","register_sub_id":"101","register_pk":"105022","name":"元屋商店主屋","kana":"もとやしょうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町字城甲660-2","lat":34.485397,"lng":134.183319,"geo_status":"db","era":"明治中期／明治後期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0197","desc":"道路に南面して建つ。東西棟，入母屋造，本瓦葺のつし２階建で，平面規模は桁行７間梁行５間。東方を下手とし，上手の西面に桁行４間，寄棟造，桟瓦葺の座敷棟がとり付く。入母屋の破風や，つし２階の梁端を塗込めるなど防火的なつくりとする点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004032"},{"id":"00005362","register_sub_id":"101","register_pk":"106350","name":"料亭二蝶大座敷","kana":"りょうていにちょうおおざしき","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県高松市百間町7-7","lat":34.34476883,"lng":134.05359283,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積274㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0288","desc":"主屋の南方に東西棟で建つ大広間棟で，内部は桁行９間半，梁間３間半で，６５畳半の座敷とし，東端に舞台，西端に２畳の上段などから成る床飾りを備える。天井を折上げ船底天井とするなど随所に凝ったつくり。設計は東京の建築家谷川増太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005362"},{"id":"00005364","register_sub_id":"101","register_pk":"106352","name":"料亭二蝶表門","kana":"りょうていにちょうおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県高松市百間町7-7","lat":34.34497886,"lng":134.0535311,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造、瓦葺及び銅板葺、間口2.7m、塀延長27m付","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0290","desc":"敷地北辺の西寄りに門口を開き，東西に外塀を延ばす。表門は間口１間半規模，東西棟，切妻造，桟瓦葺の薬医門で，軒先を銅板葺とする。外塀は庵治石基礎上に建つ真壁造の屋根付塀で，腰高く縦板張とし，小壁に窓を開けた端正なつくりで景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005364"},{"id":"00005361","register_sub_id":"101","register_pk":"106349","name":"料亭二蝶主屋","kana":"りょうていにちょうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県高松市百間町7-7","lat":34.34493372,"lng":134.05360169,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積173㎡","structure_material":"木造2階一部平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0287","desc":"高松城の東南方，繁華街の一本南の通りに北面する敷地の東北部に建つ。Ｌ字形平面を持ち，２階建部から西に東西棟，入母屋造，桟瓦葺，平屋建を突きだし，玄関・帳場等とする。玄関部は内外を数寄屋意匠でまとめ，料亭に相応しい表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005361"},{"id":"00005363","register_sub_id":"101","register_pk":"106351","name":"料亭二蝶茶室","kana":"りょうていにちょうちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県高松市百間町7-7","lat":34.34485293,"lng":134.05351062,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0289","desc":"玄関の西南方，大座敷の西北方に位置する。８畳の茶室で，西面に床の間を配し，東面には渡廊下に面して前室，南面には縁側を設ける。床柱の変木，長押の半割竹，蒲組天井など建材にも趣向を凝らす。設計は大座敷同様，香川県出身の谷川増太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005363"},{"id":"00004029","register_sub_id":"101","register_pk":"105019","name":"旅館いしや","kana":"りょかんいしや","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県さぬき市志度字田中598-1","lat":34.32321882,"lng":134.17547931,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積248㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0194","desc":"旧志度街道に北面して建つ。桁行５間半梁間４間，東西棟，片入母屋造，本瓦葺のつし２階建で，南北両面に下屋を差し掛ける。正面つし２階は白漆喰塗で，虫籠窓を２箇所に配し，虫籠窓中央の縦桟及び隅部柱型に黒漆喰の模様を入れて変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004029"},{"id":"00006936","register_sub_id":"101","register_pk":"107918","name":"旅館晩翠離れ屋","kana":"りょかんばんすいはなれや","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県観音寺市観音寺町字上松甲3099-1","lat":34.13001175,"lng":133.65306742,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"37 － 0319","desc":"主屋の南方に坪庭を介して南北棟で建つ。桁行６間半梁間３間半規模、切妻造桟瓦葺の２階建で、北面から西面にかけて銅板葺の庇をまわす。２階には３６畳大の広間を設け、天井は折上格天井とし、北面の座敷飾りには床柱として径１尺程度の楓の珍木を据える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006936"},{"id":"00006935","register_sub_id":"101","register_pk":"107917","name":"旅館晩翠本館","kana":"りょかんばんすいほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県観音寺市観音寺町字上松甲3099-1","lat":34.13005577,"lng":133.65291752,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"37 － 0318","desc":"遍路道に面する敷地の北東奧に位置する。入母屋造桟瓦葺で南北に庇を設ける平屋建で、東にトコや棚、付書院を備える主室１０畳を、西に８畳の続き間、その北に８畳間を配し、南・北・西の３面に縁廊下をまわす。座敷飾りなどに手堅い意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006935"},{"id":"00009846","register_sub_id":"101","register_pk":"195675","name":"旭館","kana":"あさひかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県喜多郡内子町内子2307他","lat":33.55461006,"lng":132.65444454,"geo_status":"db","era":"大正15／昭和中期改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積273㎡、塔屋付","structure_material":"木造平屋一部2階建","registered":"2013.12.24(平成25.12.24)","register_no":"38 － 0109","desc":"切妻造桟瓦葺の旧映画館。西正面は中央をわずかに張出し、上端は起り付で三段に切下げ、繰形と歯飾りで飾る。中央入口上にヴェランダ、頂部に六角平面の太鼓櫓が載る。内部は正面側が舞台、両脇が通路で、奥寄りに二階客席を設ける。昭和前期の賑わいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009846"},{"id":"00002179","register_sub_id":"101","register_pk":"103169","name":"石崎汽船本社","kana":"いしざききせんほんしゃ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県松山市三津1-4-9","lat":33.86522769,"lng":132.71143004,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積128㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0010","desc":"三津港波止場入口に立地する鉄筋コンクリート造２階建，陸屋根造の事務所建築で，設計は松山に縁の深い木子七郎。正面は左右対称形で，中央部を薄く張出して柱型の間に橙色，両側に白色タイルを張る。瀬戸内海海運で栄えた三津浜を象徴する建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002179"},{"id":"00004052","register_sub_id":"101","register_pk":"105042","name":"梅美人酒造事務所","kana":"うめびじんしゅぞうじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県八幡浜市1557-2","lat":33.46520407,"lng":132.42589474,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0053","desc":"街道に東面して建つ。桁行８間梁間５間規模，南北棟，寄棟造，桟瓦葺の木造２階建で，正側面をタイル張として洋風に見せる。腰は花崗石のルスチカ積，柱型の間に上げ下げ窓を配し，パラペットを背面側端部に廻す。造り酒屋店舗事務所の洋風化を示す事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004052"},{"id":"00001760","register_sub_id":"101","register_pk":"102750","name":"小藪温泉本館","kana":"おやぶおんせんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県大洲市肱川町宇和川","lat":33.45316962,"lng":132.66853694,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造3階建、瓦葺、建築面積181㎡","structure_material":"木造3階建","registered":"2000.09.26(平成12.09.26)","register_no":"38 － 0009","desc":"伊予灘に注ぐ肱川上流部の支流，小藪川に面して建つ明治９年創業の温泉旅館。木造総３階建，入母屋造・桟瓦葺で，各階とも出桁庇を付ける。１階は食堂，客室は２階３室，３階６室である。全体にたちの高い和風建築で，湯治場の象徴的な存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001760"},{"id":"00010071","register_sub_id":"101","register_pk":"196218","name":"木屋旅館本館","kana":"きやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県宇和島市本町追手2-86-12","lat":33.21855607,"lng":132.56828606,"geo_status":"db","era":"明治44／平成23改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積269㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"38 － 0110","desc":"宇和島城下の南東側で、通りに南面する二階建の木造旅館。一階は二〇メートル超の間口に差物を通し、出格子を設ける。桁行中央部を玄関ホールや階段室とし、東西に配する客室では、室ごとに意匠を違えた座敷飾を備える。城下町の風情を伝える和風旅館である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010071"},{"id":"00014538","register_sub_id":"101","register_pk":"513952","name":"旧梅野商会主屋（砥部むかしのくらし館）","kana":"きゅううめのしょうかいおもや（とべむかしのくらしかん）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県伊予郡砥部町大南701-1他","lat":33.73831667,"lng":132.79288889,"geo_status":"db","era":"明治38年／昭和前期・同25年・同37年・令和2年改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"38 - 0171","desc":"町並みの中心部角地にある砥部焼窯元の店舗兼住居。切妻造平入桟瓦葺のつし二階建、正面は真壁造で二階に格子窓を開き、一階は表と前土間をショールームに改修していたが、当初の格子を整備した。一〇畳座敷は琵琶床と付書院を備えて窯元の隆盛を窺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014538"},{"id":"00014539","register_sub_id":"101","register_pk":"513953","name":"旧梅野商会蔵（砥部むかしのくらし館）","kana":"きゅううめのしょうかいくら（とべむかしのくらしかん）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県伊予郡砥部町大南701-1他","lat":33.73833611,"lng":132.79267778,"geo_status":"db","era":"明治38年／昭和37年改修、令和2年移築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積81㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"38 - 0172","desc":"砥部焼窯元の土蔵で元は店舗北隣の辻角に位置した。切妻造桟瓦葺の土蔵造二階建、小屋組はトラス構造、元は腰板張で道に出荷口を設けた。出荷作業用の倉庫で、庇付の窓が多く、吹抜は砥部焼の荷揚げ荷降ろしに用いた。街路沿いに位置して砥部焼の歴史を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014539"},{"id":"00006254","register_sub_id":"101","register_pk":"107238","name":"旧下芳我家住宅主屋","kana":"きゅうしもはがけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県喜多郡内子町内子1946他","lat":33.55265259,"lng":132.65316879,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部平屋建、瓦葺、建築面積248㎡、渡廊下付","structure_material":"木造2階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"38 － 0074","desc":"内子町八日市護国伝建地区に続く商店街通りに北面して建つ。間口は約１９ｍの規模で木造２階建，入母屋造。南側に木造平屋建の離れが付く。正面は白漆喰と鼠漆喰を塗り分けて意匠を凝らし，屋根は千鳥破風に鶴の懸魚を付ける。重厚な町並み景観を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006254"},{"id":"00014696","register_sub_id":"101","register_pk":"515238","name":"旧村上家住宅貸家","kana":"きゅうむらかみけじゅうたくかしや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県大洲市大洲字志保町東378","lat":33.50676667,"lng":132.54842222,"geo_status":"db","era":"江戸後期／昭和前期・令和元年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積39㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"38 - 0181","desc":"大洲城下の志保町通に西面する付属屋北隣に建つ町家。二階建切妻造平入桟瓦葺で下屋を付し、二階前面には出窓を設ける。内部一階は前土間形式で、二階は二室で西室を床構え付座敷とし、縁を付して通りを望む。建ちが低く、地域の歴史的景観をつくる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014696"},{"id":"00014110","register_sub_id":"101","register_pk":"508370","name":"旧八木商店本店内蔵","kana":"きゅうやぎしょうてんほんてんうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-1他","lat":34.10741389,"lng":132.96712222,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積36㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0159","desc":"住居棟南に接続する内蔵。土蔵造二階建、切妻造本瓦葺。切石積基壇上に建ち、壁は鉢巻まで漆喰塗込め、腰は竪板張。東面の土戸の開口枠を花崗岩で精緻につくる。内部は１、２階とも１室で、書類や貴重品を収納。小屋組はキングポストトラス。庭の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014110"},{"id":"00014112","register_sub_id":"101","register_pk":"508372","name":"旧八木商店本店表塀","kana":"きゅうやぎしょうてんほんてんおもてへい","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-2他","lat":34.10724444,"lng":132.96740556,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造、瓦葺、総延長28m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0161","desc":"店舗から南に延びる通りに面した表塀。柱を半間毎に立て鉄棒の控えをとり、腰は板張、上部は土壁で欄間に開口を開く。屋根は桟瓦葺。離れ位置から高さを低め、離れ両脇に潜戸を設けて庇を架ける。総延長２８メートル。蟹工船で財をなした豪商の表構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014112"},{"id":"00014108","register_sub_id":"101","register_pk":"508368","name":"旧八木商店本店座敷","kana":"きゅうやぎしょうてんほんてんざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-1他","lat":34.10746667,"lng":132.96733056,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0157","desc":"店舗棟の西に建つ平屋建の入母屋造桟瓦葺。続き間座敷の南に入側を設け縁を廻す。襖や板戸の日本画は大智勝観作。座敷の床柱に栂の四方柾を用いる等良材を多用。小屋組はトラス風。天井が高く、縁にはガラス戸を建て廻らし庭を望む。近代和風の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014108"},{"id":"00014109","register_sub_id":"101","register_pk":"508369","name":"旧八木商店本店住居棟","kana":"きゅうやぎしょうてんほんてんじゅうきょとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-1他","lat":34.10753056,"lng":132.96715833,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積344㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0158","desc":"座敷棟の西に建つ住居棟。寄棟造で通り土間両脇を切妻造とする桟瓦葺。通り土間の北に台所、南に玄関の間、居間、茶の間を並べ、奥には続き間座敷等四室を配する。座敷は赤松の床柱の床棚を備え、襖を菊文の布張、欄間を菊透彫とした、寛いだ空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014109"},{"id":"00014107","register_sub_id":"101","register_pk":"508367","name":"旧八木商店本店店舗","kana":"きゅうやぎしょうてんほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-1他","lat":34.10741389,"lng":132.96745,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0156","desc":"波止浜港の本町通りで廻船業を営んだ商家の東面する店舗。つし二階建入母屋造桟瓦葺。正側面に下屋を廻す。南に座敷を配し正面に切妻を見せる。東面北に玄関を開け南は出格子を建てる。玄関土間沿いに一二畳、南に座敷二室を配し、いずれも良材を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014107"},{"id":"00014111","register_sub_id":"101","register_pk":"508371","name":"旧八木商店本店離れ","kana":"きゅうやぎしょうてんほんてんはなれ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県今治市波止浜二丁目406-1他","lat":34.10721111,"lng":132.96734167,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0160","desc":"敷地南西に位置する隠居屋。表塀越しに見える平屋建で切妻造桟瓦葺。Ｌ字形平面で西に続き間座敷、南に水屋付４畳半茶室を配置。茶室は床柱を赤松の皮付丸太とし下地窓を開けるが、南西面には大きなガラス障子を建て明るく安らいだ風情。庭からの点景をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014111"},{"id":"00004058","register_sub_id":"101","register_pk":"105048","name":"佐々木酒造主屋","kana":"ささきしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県伊予郡砥部町総津785","lat":33.62839941,"lng":132.79822104,"geo_status":"db","era":"明治41頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0059","desc":"村内中央を南北に通る旧街道に東面して建つ。南北に長い敷地の北方に位置し，北東部に庭園をとる。間口７間規模で，外観は真壁造とし，中央に店舗の入口，その北に出格子窓を配し，２階北方に座敷を設ける。１階庇の出桁を支持する持送り板に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004058"},{"id":"00003715","register_sub_id":"101","register_pk":"104705","name":"篠永酒造主屋","kana":"しのながしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県四国中央市具定町正之森250-1","lat":33.96810272,"lng":133.52557658,"geo_status":"db","era":"明治19頃／大正6増築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積186㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"38 － 0044","desc":"市北部を東西に横断する四国霊場八十八ヶ所遍路道に面して建つ。入母屋造，桟瓦葺，平入の木造つし２階建。腰竪板張の真壁造で，身舎を出桁造とし，妻には狐格子をあしらう。大棟の胴板には波間に泳ぐ魚を象った飾瓦を張付ける。巡礼路の上質な景観構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003715"},{"id":"00003716","register_sub_id":"101","register_pk":"104706","name":"篠永酒造門","kana":"しのながしゅぞうもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県四国中央市具定町正之森250-1","lat":33.96796669,"lng":133.52562891,"geo_status":"db","era":"明治19頃","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造、瓦葺、間口1.8m、左右袖塀付","structure_material":"木造","registered":"2003.12.01(平成15.12.01)","register_no":"38 － 0045","desc":"主屋の南側に接続し，街路に面して建つ。間口１間，桟瓦葺，一軒疎垂木とした門で，棟の両端部に主屋と同様の雲形の鳥衾をたちあげ，門の両脇には主屋の腰竪板張と高さを揃えた袖壁を配する。簡素ながら丁寧なつくりで，街路景観に彩りを添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003716"},{"id":"00002698","register_sub_id":"101","register_pk":"103688","name":"上甲家住宅","kana":"じょうこうけじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県宇和島市吉田町東小路甲71-1","lat":33.28000935,"lng":132.54051914,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造平屋建、瓦葺、建築面積174㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0025","desc":"市中心部にあり，酒・醤油販売等を生業とした商家の建物。大規模な和小屋を架けた切妻造平入の土蔵造とし，正面の真壁の上部に格子形の窓を左右対称に配する。現在，住居，事務所，食堂として利用し，街路景観の重要な要素として，町民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002698"},{"id":"00002180","register_sub_id":"101","register_pk":"103170","name":"住友化学工業愛媛工場歴史資料館","kana":"すみともかがくこうぎょうえひめこうじょうれきししりょうかん","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県新居浜市惣開町5-1","lat":33.96112493,"lng":133.26166255,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0011","desc":"住友銀行新居浜支店として建設。港近くに位置する。野口孫市率いる住友臨時建築部の最初期の作品で，軒回りの密度の高いディテールと，陸アーチと水平目地，胴蛇腹とによる端正なファサード構成に初期住友営繕の作風の一端がうかがわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002180"},{"id":"00003159","register_sub_id":"101","register_pk":"104149","name":"都築酒店店舗及び主屋","kana":"つづきさけてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県喜多郡内子町小田322","lat":33.57027355,"lng":132.80432842,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積122㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0036","desc":"街路に面して建つ。妻面は塗込とし，両妻街路側に袖卯建を張り出す。大戸口が改造されている他は格子戸の建具も良く残り，内部に箱階段を備える。２階街路側の半分に手摺を設けて開放的な作りとし，２階階高を高く取るなど，明治期の店舗兼住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003159"},{"id":"00008073","register_sub_id":"101","register_pk":"128904","name":"森家住宅主屋","kana":"もりけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市三津1-191他","lat":33.86523033,"lng":132.71234834,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積156㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"38-0094","desc":"通りに東面して建つ。間口８．８ｍの木造２階建で、その南に通路を挟んで炊事場や風呂などを設ける。切妻造桟瓦葺、正・背面に下屋庇を付ける。正面は２階壁面を軒裏まで銅板張とし、１階は北寄りの腰に大きな御影石を貼るなど、特色ある表情を造り上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008073"},{"id":"00003752","register_sub_id":"101","register_pk":"104742","name":"川田家住宅蔵","kana":"かわだけじゅうたくくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町2165","lat":33.42650028,"lng":134.00727629,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0109","desc":"問屋業時代の物品蔵。主屋の北西に位置し，南北棟で建つ。桁行４間梁間２間半規模，切妻造，桟瓦葺の２階建土蔵で，東面南寄りに戸口を設ける。外観は土佐漆喰塗壁に５段の水切瓦を付けた土蔵建築で，破風部等にも丁寧な仕事ぶりが窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003752"},{"id":"00003751","register_sub_id":"101","register_pk":"104741","name":"川田家住宅主屋","kana":"かわだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡田野町2165","lat":33.4262867,"lng":134.00734765,"geo_status":"db","era":"明治元","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積153㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0108","desc":"旧国道に南面する敷地に道路からやや退いて東西棟で建つ。桁行６間梁間４間半規模，切妻造，桟瓦葺の木造平屋建で，南面全面に下屋を架ける。西方を下手とし，東南角に８畳座敷を設け，Ｌ字型に縁を廻す。幕末から明治初期にかけての商家の表構えをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003751"},{"id":"00006341","register_sub_id":"101","register_pk":"107324","name":"河田商店店舗兼主屋","kana":"かわだしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡安田町大字安田1791","lat":33.43739534,"lng":133.98194921,"geo_status":"db","era":"明治期／昭和中期改修","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0230","desc":"通りに東面して建つ木造平屋建の町家。桁行５間梁間７間の切妻造平入で、屋根は左桟瓦葺とする。背面南寄りに釜屋を突出する。内部は当初２列６室の居室であったが、表側の板間と下屋部分を土間に改修した。当地の町家の伝統を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006341"},{"id":"00012251","register_sub_id":"101","register_pk":"353052","name":"旧竹村呉服店主屋","kana":"きゅうたけむらごふくてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県高岡郡佐川町字東町甲1300","lat":33.499204,"lng":133.289512,"geo_status":"db","era":"安永6年(1777)頃／明治初期・平成6年・同27年改修、大正前期増築","year":1777,"year_source":"db","year_min":1777,"year_max":1777,"year_label":null,"structure":"木造2階建、瓦葺、建築面積113㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"39-295","desc":"佐川町中心部に位置する旧呉服店の主屋。木造二階建、建築面積一一三平方メートルで、東寄りを土間とし、西寄りの床上部に二列各三室を配す。屋根は街路側に妻を向け桟瓦を葺く。北六畳間の座敷は、長押を廻さず簡素な造りとするなど、古式を残す民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012251"},{"id":"00012252","register_sub_id":"101","register_pk":"353053","name":"旧竹村呉服店店舗及び表蔵","kana":"きゅうたけむらごふくてんてんぽおよびおもてくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県高岡郡佐川町字東町甲1300","lat":33.499135,"lng":133.289547,"geo_status":"db","era":"文政11年(1828)頃／明治5年頃・平成6年・同27年改修","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"店舗 木造2階建、瓦葺、建築面積60㎡ 表蔵 土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"店舗 木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"39-296","desc":"敷地南端、主屋の街路側に建つ。西寄に畳敷のミセを配し、中央部は土間とし、東端部に表蔵を配して一体に屋根をかける。店舗部分の正面には庇をかけ、腰は店舗・表蔵とも海鼠壁とするが、表蔵は四半貼とし特徴ある外観を創る。地域の歴史を今に伝える建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012252"},{"id":"00012253","register_sub_id":"101","register_pk":"353054","name":"旧竹村呉服店土蔵","kana":"きゅうたけむらごふくてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高岡郡佐川町字東町甲1300","lat":33.499313,"lng":133.289466,"geo_status":"db","era":"明治中期／平成6年・同27年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"39-297","desc":"敷地北西隅に建つ二階建、置屋根形式の土蔵。小屋は登梁を折置とし、登梁上に棟木、母屋桁、軒桁を渡し、垂木を用いず直接化粧板を置く架構。外観は庭に面する東・南を漆喰塗とするが、西・北面は一部板張とする。庭と一体となり伝統的な敷地景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012253"},{"id":"00011004","register_sub_id":"101","register_pk":"208974","name":"旧三浦家住宅店舗","kana":"きゅうみうらけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県須崎市青木町7-1","lat":33.389903,"lng":133.289544,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0284","desc":"土蔵造二階建、東西棟の寄棟造、桟瓦葺で、東と南が道路の敷地南東隅に建つ。一階は南面中央に正玄関、東面に脇玄関を設け、高い格天井の事務所、二階は床付座敷や板間とする。出桁造で三段持ち出しの軒廻り、腰石張で黒漆喰塗の外壁など、上質で重厚な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011004"},{"id":"00006755","register_sub_id":"101","register_pk":"107738","name":"久保呉服店店舗兼主屋","kana":"くぼごふくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1849","lat":33.438648,"lng":133.98137195,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0221","desc":"町のほぼ中心の角地に東面して建つ。桁行６間、梁間４間半、木造平屋建、切妻造、桟瓦葺とする。北側に間口４間の店舗を配し、南側にトコ付の座敷６畳と次の間４畳半を並べ、敷地南端の庭に沿って縁側を設ける。妻側の竪板張の外観が往時の雰囲気を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006755"},{"id":"00003755","register_sub_id":"101","register_pk":"104745","name":"隅田家住宅主屋","kana":"すみだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡田野町2363-1","lat":33.42696606,"lng":134.00353447,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0112","desc":"旧国道に南面して東西棟で建つ。桁行３間半梁間５間半規模，切妻造，桟瓦葺の木造２階建で，主として１階を店舗，２階を居住部とし，１階正面中央に８寸角の柱を入れる。たちの高いつくりに特徴があり，周囲の低平な家並みの中で際だった存在になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003755"},{"id":"00003757","register_sub_id":"101","register_pk":"104747","name":"隅田家住宅精米工場","kana":"すみだけじゅうたくせいまいこうじょう","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町2363-1","lat":33.42699538,"lng":134.00360398,"geo_status":"db","era":"昭和初期／昭和20頃増築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0114","desc":"主屋の東側に東西棟で建つ。桁行３間梁間５間半，切妻造，桟瓦葺の木造平屋建で，南面に下屋を差し掛けてつし２階建風の外観をつくる。米穀商に欠くことの出来ない施設で，戦後直ぐに背面側桁行３間分をトラス架構で拡張している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003757"},{"id":"00001969","register_sub_id":"101","register_pk":"102959","name":"竹崎家住宅（旧高田屋）蔵","kana":"たけざきけじゅうたく（きゅうたかだや）くら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1699","lat":33.42465842,"lng":134.02186975,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0019","desc":"国道５５号線に面した角地に建つ。桁行５間，梁行２間で，西側の桁行２間分を２階建とし，南の平の面に入口を設け，主屋土間を蔵前とする。外観は，石積基礎，腰を押縁下見とし，上部の土佐漆喰壁に水切瓦を付けるなど当地方土蔵建築の特色を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001969"},{"id":"00001967","register_sub_id":"101","register_pk":"102957","name":"竹崎家住宅（旧高田屋）主屋","kana":"たけざきけじゅうたく（きゅうたかだや）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1699","lat":33.42468946,"lng":134.02171847,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0017","desc":"樟脳業で栄え，民権運動の指導者を出した竹崎家の店舗兼住宅で，国道に面する蔵の南方に建つ。桁行３間，梁行６間，南北棟，切妻造，桟瓦葺，平入の主体部の南妻面に奥行１間の下屋をだし，北に方２間の土間兼蔵前を突き出す。平屋建商家建築の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001967"},{"id":"00003762","register_sub_id":"101","register_pk":"104752","name":"谷雄三家住宅主屋","kana":"たにゆうぞうけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡田野町字住吉南2425－1","lat":33.42681997,"lng":134.00354182,"geo_status":"db","era":"明治7","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建一部2階建、瓦葺、建築面積80㎡","structure_material":"木造平屋建一部2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0119","desc":"旧国道に北面して東西棟で建つ。桁行４間半梁間５間，切妻造，桟瓦葺の木造つし２階建で，正面西方を土間，東方をミセに充て，奥に６畳２室を並べる。正面下屋付きで，つし２階は土佐漆喰塗壁，ミセ正面には出格子をはめて商家の表構えを整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003762"},{"id":"00006262","register_sub_id":"101","register_pk":"107246","name":"つとや店舗兼主屋","kana":"つとやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡安田町大字安田1670","lat":33.43729232,"lng":133.98032144,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積75㎡","structure_material":"木造平屋一部2階建","registered":"2007.07.31(平成19.07.31)","register_no":"39 － 0215","desc":"北側道路に面して建つ町家建築。桁行４間，梁間５間の規模で，木造平屋一部２階建，切妻造，桟瓦葺とする。表土間を店とし，東寄り通り土間に作業場，奥に８畳座敷を設ける。２階には４畳半２室を設ける。正面下屋上部に水切り瓦を付け，地域的特色をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006262"},{"id":"00006348","register_sub_id":"101","register_pk":"107331","name":"西岡呉服店店舗","kana":"にしおかごふくてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡安田町大字安田1807","lat":33.43785893,"lng":133.98112644,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積107㎡","structure_material":"木造2階一部平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0216","desc":"町のほぼ中心地に位置し、角地に東面して建つ。桁行７間、梁間４間半、木造２階一部平屋建で、切妻造、桟瓦葺とする。１階店舗内部は土間と畳敷部分からなり、つし２階が倉庫、２階が作業場となる。妻側の竪板張や漆喰塗仕上げの外観が往時の雰囲気を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006348"},{"id":"00001970","register_sub_id":"101","register_pk":"102960","name":"西尾家住宅主屋","kana":"にしおけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡奈半利町乙1578","lat":33.42590866,"lng":134.02130749,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積124㎡","structure_material":"木造平屋一部2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0020","desc":"旧道に面して建つもと旅籠屋。桁行３間半，梁行５間，東西棟，切妻造，桟瓦葺の平屋建の西側に桁行２間半規模の２階屋を増築。平屋部分は，４畳半を２列３室に並べた６間取で，旧道沿いの北面に下屋を出す。２階屋は二重屋根風に妻面をみせる点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001970"},{"id":"00003167","register_sub_id":"101","register_pk":"104157","name":"濱田家住宅店舗","kana":"はまだけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1564-3","lat":33.4259415,"lng":134.02188293,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0071","desc":"奈半利町中心街の三叉路の北西角地に建つ。桁行５間梁間５間，東西棟，切妻造の木造つし２階建店舗の北に桁行３間半規模の平屋建が南北棟で取り付く。現在は呉服店として南北店舗を一体的に使用する。もと造り酒屋部とともに奈半利の町並み景観の中心的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003167"},{"id":"00003168","register_sub_id":"101","register_pk":"104158","name":"濱田家住宅煉瓦蔵","kana":"はまだけじゅうたくれんがぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1564-3","lat":33.425907,"lng":134.02186642,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、瓦葺、建築面積34㎡","structure_material":"煉瓦造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0072","desc":"店舗の北に接して建つ。桁行８．５ｍ梁間４ｍ規模の木骨造外部煉瓦長手積で，桟瓦葺の寄棟屋根を東西棟で架ける。北店舗を蔵前とした平入で，内部東方に半円の廻り階段を設置し，２階に洋風手摺を廻す。周囲の水切瓦と土佐漆喰の土蔵と対照をなし際だつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003168"},{"id":"00003165","register_sub_id":"101","register_pk":"104155","name":"東山家住宅蔵","kana":"ひがしやまけじゅうたくくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1281-2","lat":33.42362121,"lng":134.02125038,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積87㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0069","desc":"主屋の北方に建つ。桁行４間半梁間２間半，南北棟，切妻造，桟瓦葺の２階建土蔵の東に桁行２間半，東西棟，切妻造，桟瓦葺で南方に下屋を延ばした平屋建土蔵が取り付く。敷地西北隅の角地に水切瓦と土佐漆喰塗壁を見せる。奈半利の町並み景観の核となる存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003165"},{"id":"00003163","register_sub_id":"101","register_pk":"104153","name":"東山家住宅主屋","kana":"ひがしやまけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1281-2","lat":33.42348482,"lng":134.02123206,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0067","desc":"国道から南に入った市街中心地に位置する。道路に西面して南北棟で建つ。桁行５間半梁行６間規模，入母屋造，桟瓦葺のつし２階建で，東に茶の間，南に釜屋を付属させる。北方上手正面には連子格子をはめ，つし２階は真壁風につくり中央に特徴的な窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003163"},{"id":"00003743","register_sub_id":"101","register_pk":"104733","name":"普光江家住宅主屋西棟","kana":"ふこうえけじゅうたくしゅおくにしとう","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡田野町2051","lat":33.42778837,"lng":134.01022407,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0100","desc":"主屋東棟の西に建つ店舗部で，東棟とは屋根を一体に架ける。桁行３間梁間５間規模，東西棟，切妻造，桟瓦葺の平入，木造つし２階建で，内部北側は土間，南側は釜屋とする。帳場及び居住部の東棟と一体となって商家の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003743"},{"id":"00003742","register_sub_id":"101","register_pk":"104732","name":"普光江家住宅主屋東棟","kana":"ふこうえけじゅうたくしゅおくひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡田野町2051","lat":33.42781931,"lng":134.01032431,"geo_status":"db","era":"明治初期／大正13移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0099","desc":"田野町の中心街弓道に北面して建つ。桁行４間梁間４間規模，東西棟，切妻造，桟瓦葺の木造つし２階建で，内部は田の字型４室間取とし，道路沿いの北面には連子を入れる。東妻面の土佐漆喰塗壁に３段の水切瓦が土佐の土蔵造建築の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003742"},{"id":"00009675","register_sub_id":"101","register_pk":"194671","name":"前田家住宅店舗兼主屋","kana":"まえだけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸市本町5-1736-8","lat":33.50137998,"lng":133.8977987,"geo_status":"db","era":"昭和4頃／昭和後期改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"39 － 0273","desc":"遍路道の角地に北面する。つし二階建、入母屋造及び切妻造桟瓦葺で、東南隅に平屋を張出す。軸部は良材を用いて丁寧につくる。外壁は腰を瓦張とし、屋根に左桟瓦を葺き、東壁面に土佐漆喰の水切瓦を四段付ける等、当地方の住宅の特色をよく示す良質な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009675"},{"id":"00009676","register_sub_id":"101","register_pk":"194672","name":"前田家住宅土塀","kana":"まえだけじゅうたくどべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸市本町5-1736-8","lat":33.50130561,"lng":133.89770619,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土塀、瓦葺、延長5.8m","structure_material":"土塀","registered":"2013.06.21(平成25.06.21)","register_no":"39 － 0274","desc":"主屋南西端に接続し、敷地の西面を画する。南北棟桟瓦葺。北半を主屋南面庇の軒高に揃え、南半を高さを抑えて連ねる。全体を土佐漆喰で塗込めており、棟にはひも漆喰を施して台風等から守る工夫がなされる。東面では左桟瓦を使用し、地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009676"},{"id":"00012845","register_sub_id":"101","register_pk":"367748","name":"岬観光ホテル新館","kana":"みさきかんこうほてるしんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県室戸市室戸岬町字白濱4037他","lat":33.30150278,"lng":134.18630972,"geo_status":"db","era":"昭和39年頃","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"木造2階建、瓦葺、建築面積162㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 299","desc":"本館背面に接続する寄棟造の二階建で、外壁縦板張とする。内部は上下階とも海を望む東側に和風の客室三室を設け、一部客室に浴室・便所を備える。製材を用い、水平・垂直を強調した床や欄間の意匠が時代感覚を現す。観光地室戸岬の発展期の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012845"},{"id":"00012844","register_sub_id":"101","register_pk":"367747","name":"岬観光ホテル本館","kana":"みさきかんこうほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県室戸市室戸岬町字白濱4037他","lat":33.30150278,"lng":134.18630972,"geo_status":"db","era":"昭和9年頃／昭和中期改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階一部3階地下1階建、瓦葺、建築面積274㎡","structure_material":"木造2階一部3階地下1階建","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 298","desc":"室戸岬南端の海岸沿いに建つホテル。木造二階建、切妻造妻入で、西面に玄関ポーチを出し、下見板張の妻に窓を設けた洋風の外観とする。玄関や廊下は大壁上部に繰形を廻すなど洋風とするが、客室は畳敷の和室とする。観光開発萌芽期の室戸岬の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012844"},{"id":"00006340","register_sub_id":"101","register_pk":"107323","name":"南商店内塀","kana":"みなみしょうてんうちべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1771-1","lat":33.43697907,"lng":133.98168936,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"コンクリート造、瓦葺、延長7.0m","structure_material":"コンクリート造","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0229","desc":"主屋背面の中坪を限るコンクリート塀。東側釜屋と南側便所の目隠しで、折れ曲がり７．０ｍ、総高１．７ｍ、基底幅０．５ｍ。基部はモルタルで亀甲形に塗る。壁はヒル石を混ぜたモルタル塗で竪目地を表し、頂部は瓦を葺く。丁寧な造りで庭園景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006340"},{"id":"00006344","register_sub_id":"101","register_pk":"107327","name":"南商店外塀","kana":"みなみしょうてんそとべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1771-1","lat":33.43679467,"lng":133.98154237,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"コンクリート造、瓦葺、延長6.0m","structure_material":"コンクリート造","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0228","desc":"敷地の南西隅を限る塀。西側道路から敷地の南面へ折れ曲がる延長６．０ｍ。基部は大ぶりの浜石を切込み矧ぎで３段積とする。壁体はコンクリート造で、蛇腹２段を造り、頂部には桟瓦を葺く。総高１．８ｍ、基底幅０．６ｍ。街路景観のアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006344"},{"id":"00006339","register_sub_id":"101","register_pk":"107322","name":"南商店店舗兼主屋","kana":"みなみしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1771-1","lat":33.43695828,"lng":133.98161925,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0227","desc":"通りに北面する、つし２階建の町家である。間口５間半の切妻造桟瓦葺で、前後に瓦葺庇がつく。内部は表を土間の店舗、奥を６畳４室とする。背面東端に釜屋、西端に渡廊下を介して便所風呂が接続。妻壁は土佐漆喰塗で水切り瓦５段で飾るなど地域的特色を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006339"},{"id":"00004456","register_sub_id":"101","register_pk":"105446","name":"矢野家住宅主屋","kana":"やのけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県土佐市高岡町甲2145-1","lat":33.4965793,"lng":133.42239383,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積112㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0170","desc":"街道に北面して建つ。間口４間，東西棟，切妻造，平入のつし２階建で，東側を通り土間とし，西側南に南北棟，切妻造，平屋建の居室部を突き出す。正面側は左瓦を使用し，外壁黒漆喰塗で，１階両脇の腰を海鼠壁とし，２階軒下部などに水切瓦を付けるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004456"},{"id":"00004062","register_sub_id":"101","register_pk":"105052","name":"山中家住宅主屋","kana":"やまなかけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県吾川郡いの町長沢131-28","lat":33.725956,"lng":133.30687,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、瓦葺、建築面積190㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0130","desc":"大森川と吉野川本流の合流点近くに位置する。木造２階建の旅館建築で，１階の平面規模は桁行９間梁行４間半とし，２階の主屋根は片入母屋に造る。地元産の良材を用いているほか，玄関上部などに鶴，亀，鯉など吉祥の漆喰鏝絵を施しているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004062"},{"id":"00002095","register_sub_id":"101","register_pk":"103085","name":"山本家住宅主屋","kana":"やまもとけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香美市土佐山田町東本町5-2-11","lat":33.60787042,"lng":133.69270062,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"39 － 0034","desc":"土佐山田町の市街を東西に貫通する旧道沿いの細長い商店街に北面して建つ。木造２階建，切妻造，桟瓦葺，平入の町家で，地元の建築家が改修して設計事務所として使用するとともに，主屋シモテ部をギャラリーとし地元の活性化にも貢献している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002095"},{"id":"00011001","register_sub_id":"101","register_pk":"208971","name":"料亭得月楼喜久の間","kana":"りょうていとくげつろうきくのま","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県高知市南はりまや町一丁目255-3他","lat":33.55896,"lng":133.544047,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0281","desc":"喜久の間は高陽の間の西に納戸付の廊下で接続している。木造平屋建、切妻造、桟瓦葺で、一二畳の西側に床とＬ型付書院を構え、南の庭園側に縁を設け、魚梁瀬杉を用いた棹縁天井を張る。長押を用いないなど、数寄屋風意匠で、高陽の間と対比的な造形をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011001"},{"id":"00011000","register_sub_id":"101","register_pk":"208970","name":"料亭得月楼高陽の間","kana":"りょうていとくげつろうこうようのま","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県高知市南はりまや町一丁目255-3他","lat":33.558882,"lng":133.544119,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0280","desc":"木造平屋建、寄棟造、桟瓦葺で、江戸時代末期の庭園に南面して建つ。ゆったり構えた大床と棚、丸窓の張り出し型の附書院、幾何学模様風の格縁天井などに見所がある。面取り材を駆使した繊細な数寄屋風で、新規性も採り入れた意欲的な造形を内包した和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011000"},{"id":"00011003","register_sub_id":"101","register_pk":"208973","name":"料亭得月楼正門","kana":"りょうていとくげつろうせいもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県高知市南はりまや町一丁目254他","lat":33.55921527,"lng":133.54414799,"geo_status":"db","era":"昭和34／昭和60改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造、瓦葺、間口5.9m、西方袖塀付","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"39-0283","desc":"はりまや橋東方、北と南が街路に面して敷地を構える。北面西寄りに建つ正門は、桟瓦葺の横長門で、両側への引き込み戸、皮剥き磨き丸太を用いた柱や桁など、新しい和風意匠を目指した独特な門であるが、老舗の格式に相応しい雄大な外観をみせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011003"},{"id":"00004441","register_sub_id":"101","register_pk":"105431","name":"料亭得月楼本館","kana":"りょうていとくげつろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県高知市南はりまや町1-17-3","lat":33.559063,"lng":133.544144,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積319㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0155","desc":"高知空襲による焼失後の復興建築。桁行１０間梁間６間規模，入母屋造，桟瓦葺の木造２階建で，北面中央東寄りに切妻造車寄を突出させて玄関とし，２階には天井に魚梁瀬杉の長尺物を用いた８０畳敷大広間を設ける。設計は高知県建築士会草創期会員の柳生濟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004441"},{"id":"00011002","register_sub_id":"101","register_pk":"208972","name":"料亭得月楼渡り廊下","kana":"りょうていとくげつろうわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県高知市南はりまや町一丁目256-4他","lat":33.558955,"lng":133.544229,"geo_status":"db","era":"昭和25／昭和32改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"39-0282","desc":"本館から南に延びる廊下、その先端の待合、客間及び高陽の間への連絡部からなり、桟瓦葺とする。廊下は桁行三間半で、磨き丸太の化粧垂木を見せた船底天井とし、二間に一間半規模の待合は網代天井になる。丁寧な数寄屋風意匠で、全体の調和がよく取れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011002"},{"id":"00009854","register_sub_id":"101","register_pk":"195683","name":"アートスペース谷尾（旧十七銀行直方支店）","kana":"あーとすぺーすたにお（きゅうじゅうしちぎんこうのおがたしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県直方市古町929-1他","lat":33.74602,"lng":130.72789524,"geo_status":"db","era":"大正2頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造及び煉瓦造2階建、鉄板葺、建築面積375㎡","structure_material":"木造及び煉瓦造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0110","desc":"角地に建つ木造二階建、鉄板葺で、南東隅を塔屋風に張出す。外壁は煉瓦風タイル小口貼で、基礎やバンド、窓台などに花崗岩を用いてアクセントとし、玄関廻りや柱形などの細部はゼツェッションでまとめる。地域のランドマークとして親しまれる、もと銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009854"},{"id":"00009853","register_sub_id":"101","register_pk":"195682","name":"石原商店店舗","kana":"いしはらしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県直方市殿町590-3","lat":33.74394755,"lng":130.72797208,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0109","desc":"前田園本店の北隣に並び建ち、木造二階建、切妻造桟瓦葺。二階正面に穿つ横長の大窓下に中二階用の小窓を並べて庇を付け、一階の軒庇とともに、三層構成の立面とする。内部のミセ上部を一部吹抜とし二階は座敷とする。前田園とともに良質な街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009853"},{"id":"00009540","register_sub_id":"101","register_pk":"194333","name":"上野ビル（旧三菱合資会社若松支店）旧分析室","kana":"うえのびる（きゅうみつびしごうしがいしゃわかまつしてん） きゅうぶんせきしつ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町1-14-1他","lat":33.90272449,"lng":130.81382588,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0083","desc":"倉庫棟の北側に東面にして建つ。木造平屋建、建築面積一一九平方メートル、切妻造瓦葺である。煉瓦造の周囲の建物にあわせて大壁造とし、窓は縦長窓、腰壁はスクラッチタイル張とする。石炭の品質分析を行った、石炭会社の現地事務所を特徴づける建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009540"},{"id":"00009539","register_sub_id":"101","register_pk":"194332","name":"上野ビル（旧三菱合資会社若松支店）倉庫棟","kana":"うえのびる（きゅうみつびしごうしがいしゃわかまつしてん） そうことう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町1-14-1他","lat":33.90243003,"lng":130.81376342,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積190㎡","structure_material":"煉瓦造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0082","desc":"本館の西側に東面して建つ。煉瓦造二階建、建築面積一九〇平方メートル、切妻造瓦葺、L字形の平面とし、東面に突出した妻に三菱の社標を掲げる。基礎や窓まわりに石材を用いるなど簡素ながらも確かなつくりで、当時の煉瓦造倉庫の技術的水準を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009539"},{"id":"00009538","register_sub_id":"101","register_pk":"194331","name":"上野ビル（旧三菱合資会社若松支店）本館","kana":"うえのびる（きゅうみつびしごうしがいしゃわかまつしてん） ほんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町1-14-1他","lat":33.90256983,"lng":130.8139627,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造3階建、建築面積465㎡","structure_material":"煉瓦造3階建","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0081","desc":"若松港に面して建つ。煉瓦造三階建、建築面積四六五平方メートル、陸屋根である。左右対称の正面で、中央に玄関を突出する。縦長窓を規則的に配した重厚な外観に対して、内部は中央の吹き抜けを取り、鋳鉄製の柱やステンドグラスを用いて華やかに仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009538"},{"id":"00009541","register_sub_id":"101","register_pk":"194334","name":"上野ビル（旧三菱合資会社若松支店）門柱及び塀","kana":"うえのびる（きゅうみつびしごうしがいしゃわかまつしてん） もんちゅうおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町1-14-1他","lat":33.90233902,"lng":130.81405407,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"門柱 煉瓦造門柱6基 塀 煉瓦造、総延長115m","structure_material":"門柱 煉瓦造門柱6基 塀 煉瓦造","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0084","desc":"敷地正面である南面の東寄りと、北面の東寄りと西寄りの三箇所に門を開き、南、東、北の三面に塀を廻らす。煉瓦造、塀は総長一一五メートル、正門の門柱は高さ二・三メートルを測る。建設当時の姿をよく残し、石炭会社の現地事務所の構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009541"},{"id":"00012254","register_sub_id":"101","register_pk":"353055","name":"江頭家住宅主屋","kana":"えがしらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県大川市大字榎津字向町746-2","lat":33.207198,"lng":130.374194,"geo_status":"db","era":"江戸末期／昭和前期・同40年代増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積286㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"40-148","desc":"間口八間、奥行八間で入母屋造妻入の直屋に切妻造の角屋を直交し居蔵造とする当地域の大規模町家特有の形式を持つ。通り土間に沿ってミセ、チョウバ、チャノマなど並べ、上手に座敷二室を配す。大戸や蔀戸も良く残り、座敷飾りには華やかな意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012254"},{"id":"00012255","register_sub_id":"101","register_pk":"353056","name":"江頭家住宅門及び塀","kana":"えがしらけじゅうたくもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県大川市大字榎津字向町746-2","lat":33.207189,"lng":130.374048,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"門 木造、瓦葺、間口1.9m、塀 木造、瓦葺、延長7.0m","structure_material":"門 木造","registered":"2018.03.27(平成30.03.27)","register_no":"40-149","desc":"主屋正面の北側に矩折で接続する。門は間口一・九メートルで、両開板扉を吊る。塀は木造で、外側を大壁とし、軒は蛇腹に仕上げ、切妻造の屋根を架け、正面妻面を塗り込める。主屋とともに耐火性を重視した構えで、街路からの歴史的景観を良好に形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012255"},{"id":"00015397","register_sub_id":"101","register_pk":"532521","name":"旧玉乃井旅館","kana":"きゅうたまのいりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福津市津屋崎四丁目1023-1","lat":33.78803333,"lng":130.46295,"geo_status":"db","era":"明治42年／昭和9年頃・同37年増築、令和3年改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積322㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0237","desc":"津屋崎海岸の東側に建つ旧旅館。通りに東面する2階建桟瓦葺で北東に玄関を付す。各階、中廊下を東西に通して客室を並べ、2階は南西に続き間座敷を配し、連窓を建てた広縁を介して海を望む。増築を重ねて、部屋数を増やし、海水浴客の賑わいを伝える旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015397"},{"id":"00007322","register_sub_id":"101","register_pk":"108304","name":"旧古河鉱業若松ビル","kana":"きゅうふるかわこうぎょうわかまつびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町1-217他","lat":33.90237,"lng":130.812698,"geo_status":"db","era":"大正8／平成16改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造2階建、銅板一部スレート葺、建築面積297㎡","structure_material":"煉瓦造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"40 － 0059","desc":"鋭角の角地に敷地を占める、煉瓦造２階建。南西隅に大塔、南東に小塔を建てる。壁面はモルタル塗で、南面と西面は煉瓦タイル貼のピラスターを付け、その間に２連の縦長窓を上下階に開け、縦線を強調する。若松港のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007322"},{"id":"00001083","register_sub_id":"101","register_pk":"102073","name":"草野歴史資料館（旧草野銀行本店）","kana":"くさのれきししりょうかん（きゅうくさのぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市草野町草野411-1","lat":33.31929858,"lng":130.63545988,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造２階建，瓦葺，建築面積177㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"40 － 0005","desc":"久留米市の東部，旧御井郡の中心地として栄えた草野地区の地元銀行建築。木造平屋建，瓦葺寄棟屋根，下見板貼りの銀行店舗で，正面に千鳥破風の車寄ポーチを突き出す。門扉，鉄柵もよく遺されており，地方銀行の様子を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001083"},{"id":"00001149","register_sub_id":"101","register_pk":"132577","name":"草野歴史資料館（旧草野銀行本店）門","kana":"くさのれきししりょうかん（きゅうくさのぎんこうほんてん）もん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市草野町草野411-1","lat":33.31942952,"lng":130.63539017,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"石造，幅員2.9m，左右柵基壇18.7m附属","structure_material":"石造","registered":"1999.06.07(平成11.06.07)","register_no":"40 － 0009","desc":"銀行本館の前庭を前面街路と側面街路に沿って鈎型に囲うもので、正面中央に正門、側面に通用門を設け、高欄風の石造土台の上に鉄柵を建てる。資料館開館（昭和５９年）にあたり復元された門扉と鉄柵は地方銀行におけるアプローチ空間の有様をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001149"},{"id":"00008600","register_sub_id":"101","register_pk":"134996","name":"髙橋家住宅店舗兼主屋","kana":"たかはしけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市博多区下呉服町72","lat":33.60221698,"lng":130.40781532,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0064","desc":"博多町人町に位置し、竪町筋に北面する。間口五・六メートル奥行一二メートルの木造二階建。切妻造桟瓦葺で正面に庇を付ける。二階は格子戸、一階はガラス戸を全面にたてる。通り土間で正面にミセを設け、二階に座敷三室を配する。標準的な博多の近代町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008600"},{"id":"00015263","register_sub_id":"101","register_pk":"530687","name":"田所商店倉庫","kana":"たどころしょうてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県北九州市八幡東区祝町二丁目1189-18","lat":33.86414167,"lng":130.82921111,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造平屋建、瓦葺、建築面積51㎡","structure_material":"煉瓦造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"40 - 0228","desc":"東山一丁目の交差点南東に建つ旧茶製品用倉庫。煉瓦造東西棟の北面西寄りを北に突出して全体矩折とし、北西を隅切とした変形の寄棟造桟瓦葺。入隅部の戸口上に庇を付し、内部は１室の板敷。小屋組はキングポスト・トラス。鉱滓煉瓦を用いた地域性豊かな倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015263"},{"id":"00014214","register_sub_id":"101","register_pk":"508844","name":"百年庭園の宿翠水（旧旅館田川離れ）企救","kana":"ひゃくねんていえんのやど すいすい（きゅう りょかんたがわはなれ）きく","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市小倉北区古船場町9-1他","lat":33.87914167,"lng":130.88152778,"geo_status":"db","era":"昭和37年／同57年改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"40 - 0197","desc":"日本庭園の池庭に面して建つ高級旅館の離れ三棟のうち中央に建つ。木造平屋建入母屋造一部切妻造銅板葺、深い軒と高欄付の張り出し縁によりあたかも池に浮かぶ小船の風情を醸す。正統的な数寄屋の構成に近代的な設備や斬新な意匠を施す近代数寄屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014214"},{"id":"00014215","register_sub_id":"101","register_pk":"508845","name":"百年庭園の宿翠水（旧旅館田川離れ）玄海","kana":"ひゃくねんていえんのやど すいすい（きゅう りょかんたがわはなれ）げんかい","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市小倉北区古船場町9-1他","lat":33.879175,"lng":130.88141389,"geo_status":"db","era":"昭和37年／同57年改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積92㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"40 - 0198","desc":"日本庭園の池庭に面して建つ高級旅館の離れ三棟のうち西寄りに建つ。木造平屋建入母屋造一部切妻造銅板葺、竹や自然木の丸太を多用する古典的な詫びた草庵風建築への志向が認められる一方、幅広格天井風の竿縁の配置など斬新な近代数寄屋の特徴がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014215"},{"id":"00014213","register_sub_id":"101","register_pk":"508843","name":"百年庭園の宿翠水（旧旅館田川離れ）菅生","kana":"ひゃくねんていえんのやど すいすい（きゅう りょかんたがわはなれ）すがお","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市小倉北区古船場町9-1他","lat":33.87908611,"lng":130.88161667,"geo_status":"db","era":"昭和37年／同57年改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積126㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"40 - 0196","desc":"北九州を代表する高級旅館の離れで、多くの賓客を迎えてきた。平屋建入母屋造一部切妻造銅板葺で、伝統的な書院風の数寄屋の造りの中に、障子戸とガラス戸との間にカーテンを設けるなど、近代数寄屋としての新たな様式を形成しようとする意欲的な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014213"},{"id":"00014216","register_sub_id":"101","register_pk":"508846","name":"百年庭園の宿翠水（旧旅館田川離れ）渡り廊下","kana":"ひゃくねんていえんのやど すいすい（きゅう りょかんたがわはなれ）わたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市小倉北区古船場町9-1他","lat":33.87906111,"lng":130.88150556,"geo_status":"db","era":"昭和37年／同57年改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"40 - 0199","desc":"高級旅館の数寄屋風離れ三棟に接続する渡り廊下。木造平屋切妻造銅板葺、床は平瓦の四半敷で節目のある丸太の柱を根石の上に立て、天井は竹を詰め打ちにするなど野趣を表現しながらも飾り気のない瀟洒な意匠で、控えめながらも重要な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014216"},{"id":"00013468","register_sub_id":"101","register_pk":"368564","name":"福岡県い業会館旧宿直棟","kana":"ふくおかけんいぎょうかいかんきゅうしゅくちょくとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県三潴郡大木町大字八町牟田3-1","lat":33.20713611,"lng":130.43318056,"geo_status":"db","era":"昭和11年／昭和18年、平成29年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"40 － 0175","desc":"本館と、本館西の勝手口から接続する。事務所の宿直等に使用した付属施設。木造平屋建入母屋造で漆喰仕上に腰竪板張と、本館と対照的な和風意匠を持つ。内部は八畳、六畳の二室を並べ、奥に台所を付す。本館とともに地域産業の近代化を物語る建物として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013468"},{"id":"00013467","register_sub_id":"101","register_pk":"368563","name":"福岡県い業会館本館","kana":"ふくおかけんいぎょうかいかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県三潴郡大木町大字八町牟田3-1","lat":33.20716111,"lng":130.43334167,"geo_status":"db","era":"昭和11年／昭和中期、平成26年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積130㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"40 － 0174","desc":"県内のい業関係５団体の事務所。木造二階建寄棟造で玄関ポーチを突出させる。外観は下見板張に付柱のスティックスタイルでまとめる。内部は一階が事務室、二階が会議室等だが、各室で天井意匠を変える等熟れた意匠を持つ。町内では希少な洋風建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013467"},{"id":"00009852","register_sub_id":"101","register_pk":"195681","name":"前田園本店倉庫","kana":"まえだえんほんてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県直方市殿町590-1","lat":33.74376968,"lng":130.72770498,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"煉瓦造及び木造2階建、瓦葺、建築面積111㎡","structure_material":"煉瓦造及び木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0108","desc":"店舗の後方に座敷などを介して東西棟で建ち、煉瓦造及び木造二階建、切妻造桟瓦葺である。東妻が出入口で西妻に鉄板張の扉を開き、周囲に窓を穿つ。外壁は鉄板張で内部をモルタル仕上とし、小屋はキングポストトラスを組む。茶などの保管用に建てられた倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009852"},{"id":"00009851","register_sub_id":"101","register_pk":"195680","name":"前田園本店店舗","kana":"まえだえんほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県直方市殿町590-1","lat":33.74381727,"lng":130.72799528,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積112㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"40 － 0107","desc":"通りに東面し、木造二階建、切妻造桟瓦葺である。正面二階は出桁造で壁を黒漆喰で仕上げ、腰部と大振りの窓枠を銅板張とし、瓦葺の庇を付ける。一階内部はケヤキの良材を用いた普請でミセなどを配し、二階は座敷とする。近代直方の商家の様相を伝える店舗。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009851"},{"id":"00010237","register_sub_id":"101","register_pk":"198070","name":"門司ゴルフ倶楽部クラブハウス北棟","kana":"もじごるふくらぶくらぶはうすきたとう","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市門司区大字吉志字稗畑175-10","lat":33.863643,"lng":130.952782,"geo_status":"db","era":"昭和35","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造平屋建一部地下1階建、鉄板葺、建築面積434㎡","structure_material":"鉄筋コンクリート造平屋建一部地下1階建","registered":"2014.10.07(平成26.10.07)","register_no":"40 － 0112","desc":"南棟と接続して建ち、東西四〇メートル南北九・一メートルを測る平屋建。キャディー室などのサービス機能を集約して設備充実を図りつつ、プレイヤー用の浴室なども配置するが、プレイヤーとキャディーの動線が交錯しないよう合理的に計画された平面をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010237"},{"id":"00010236","register_sub_id":"101","register_pk":"198069","name":"門司ゴルフ倶楽部クラブハウス南棟","kana":"もじごるふくらぶくらぶはうすみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市門司区大字吉志字稗畑175-10","lat":33.86344,"lng":130.952728,"geo_status":"db","era":"昭和35","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積1257㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"40 － 0111","desc":"桁行五五メートル梁間二二メートルを測る鉄筋コンクリート造二階建のクラブハウス。開放的で水平線を強調した立面とし、内部は打放しコンクリートの躯体で大空間を確保し、丸太の小屋を組む。いわゆるレーモンドスタイルが遺憾なく発揮されたモダニズム建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010236"},{"id":"00010238","register_sub_id":"101","register_pk":"198071","name":"門司ゴルフ倶楽部スタートハウス","kana":"もじごるふくらぶすたーとはうす","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県北九州市門司区大字吉志字稗畑175-10","lat":33.862984,"lng":130.952213,"geo_status":"db","era":"昭和35","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"40 － 0113","desc":"木造平屋建で、桁行九・四メートル、梁間三・八メートルを測る。屋根や外壁はクラブハウスと同系色のオレンジ色に近い赤色塗装を施し、丸太の桁を現す。平面は三室とし、左右を待合、中央を管理室とする。腰高の水平連続窓を設け、開放感のある構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010238"},{"id":"00004301","register_sub_id":"101","register_pk":"105291","name":"料亭金鍋表門","kana":"りょうていきんなべおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町2-516、522、523","lat":33.90412422,"lng":130.80809936,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造、瓦葺、間口1.8m、塀延長3.9m付","structure_material":"木造","registered":"2004.07.23(平成16.07.23)","register_no":"40 － 0040","desc":"北と南が道路に面した細長い敷地で，表門は北辺際にある。左右には塀が延び，西塀は折れ曲がって，表門とともに玄関前庭を区画する。間口約２ｍで角柱を立て，腕木，軒桁，垂木に丸太を用い，ガラス欄間を嵌め込むなど，近代的な数寄屋風意匠になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004301"},{"id":"00004300","register_sub_id":"101","register_pk":"105290","name":"料亭金鍋本館","kana":"りょうていきんなべほんかん","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市若松区本町2-516、522、523","lat":33.90385012,"lng":130.80818138,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造3階建、瓦葺、建築面積382㎡","structure_material":"木造3階建","registered":"2004.07.23(平成16.07.23)","register_no":"40 － 0039","desc":"木造３階建の老舗料亭。南北に細長い建物で，中廊下の東西に部屋を配した平面構成とし，２階に床・棚付３０畳の大広間を設ける。全体に良材を用い，洗練された質の高い数寄屋風で纏め，洋風も用いる。重厚な黒漆喰塗の外観は，地域の景観上，存在感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004300"},{"id":"00013007","register_sub_id":"101","register_pk":"368120","name":"料亭満佐表門及び塀","kana":"りょうていまさおもてもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区中洲一丁目103他","lat":33.59064722,"lng":130.40837222,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"表門 木造、瓦葺、間口2.2m 塀 鉄筋コンクリート造、瓦葺、総延長107m、通用門付","structure_material":"表門 木造","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 163","desc":"敷地の東西北三面を区切る塀と門。表門は西面塀北寄りに間口四・五メートルの門口を開き、外側に庇、内側に片流れ下屋を付す。塀は鉄筋コンクリート造の桟瓦葺、西面塀を腰縦板張とし、東面塀北端に通用門を設ける。老舗料亭の風格ある店構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013007"},{"id":"00013003","register_sub_id":"101","register_pk":"368116","name":"料亭満佐主屋棟","kana":"りょうていまさしゅおくとう","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区中洲一丁目103他","lat":33.59066944,"lng":130.40830833,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積236㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 159","desc":"中洲の一角にあり、主屋棟は那珂川沿いに西面して建つ。木造二階建、入母屋造及び切妻造桟瓦葺妻入で、正面北端に玄関を出す。外壁は聚楽大壁。一階に客室3室、二階に広間を設け、中廊下を通し、各室を異なる趣向の意匠とする。上質な新興数寄屋の料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013003"},{"id":"00013006","register_sub_id":"101","register_pk":"368119","name":"料亭満佐新館棟","kana":"りょうていまさしんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区中洲一丁目103他","lat":33.590625,"lng":130.40850833,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 162","desc":"主屋棟の東側に渡廊下で接続する木造平屋建、切妻造桟瓦葺。南に一二畳の座敷と次の間、北に小座敷や便所を配する。座敷は西面に踏込床、床、床脇を備え、室境は壁引込み式の欄間付襖とする。横桟のみの障子や埋込み照明の平天井など新興数寄屋の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013006"},{"id":"00013005","register_sub_id":"101","register_pk":"368118","name":"料亭満佐厨房棟","kana":"りょうていまさちゅうぼうとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区中洲一丁目103他","lat":33.59075,"lng":130.40843056,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 161","desc":"主屋棟背面に接続する切妻造、寄棟造及び入母屋造桟瓦葺の二階建で、一階中廊下の北に厨房や帳場、南に居室、二階に応接間等を設ける。居室や応接間は大壁で、横桟のみの建具や埋込み照明に細い竿縁を吹寄せで配する天井など、吉田五十八流の手法がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013005"},{"id":"00013004","register_sub_id":"101","register_pk":"368117","name":"料亭満佐離れ棟","kana":"りょうていまさはなれとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市博多区中洲一丁目103他","lat":33.59058889,"lng":130.40843333,"geo_status":"db","era":"昭和29年／昭和30年代増築","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 160","desc":"主屋棟の南東方に建つ木造平屋建、切妻造桟瓦葺銅板腰葺で、離れ、茶室、便所等からなる。離れは西面に床を設け、南東二面に縁を廻して月見台とする。茶室は東面に袋床を設け、名栗仕上の中柱や下地窓付の袖壁を備える。主屋から独立した風流な趣の離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013004"},{"id":"00005676","register_sub_id":"101","register_pk":"106664","name":"飯盛酒造主屋","kana":"いいもりしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市古枝甲122","lat":33.09236397,"lng":130.11395063,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、瓦葺、建築面積347㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0060","desc":"旧長崎街道多良往還に北面して建つ，間口１０間半の木造２階建。入母屋造，桟瓦葺で，東側土間部の外壁は塗屋造，西側の居室部は真壁造とする。居室部は１階が２列６室，２階は１０畳３室で，それぞれ表裏に縁を設ける。土間の背面南側には釜場が接続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005676"},{"id":"00001778","register_sub_id":"101","register_pk":"102768","name":"牛津赤れんが館（旧田中丸商店れんが造り倉庫）","kana":"うしづあかれんがかん（きゅうたなかまるしょうてんれんがづくりそうこ）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県小城市牛津町牛津586-1","lat":33.24764138,"lng":130.20427231,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造2階建、瓦葺、建築面積170㎡","structure_material":"煉瓦造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"41 － 0016","desc":"長崎街道の宿場町牛津の代表的商家で玉屋デパートの前身田中丸商店の煉瓦造２階建倉庫。軒下に周されたデンティル，石材と煉瓦を混用した妻面の空気孔，軽く湾曲した屋根形状などに見所をもつ。かつて商業で繁えた牛津の象徴的建築物として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001778"},{"id":"00002466","register_sub_id":"101","register_pk":"103456","name":"旧古賀銀行神埼支店","kana":"きゅうこがぎんこうかんざきしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県神埼市神埼町神埼字3-438","lat":33.308956,"lng":130.372818,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"41 － 0026","desc":"旧長崎街道に面して建つ。佐賀市に設立された古賀銀行の神埼支店として建設。正面中央にトスカナ式花崗石円柱に支持されたペディメントを配して玄関とし，モルタル洗出し仕上げでセセッション風の柱頭飾りなどを造り出す。大正期銀行支店建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002466"},{"id":"00005686","register_sub_id":"101","register_pk":"106674","name":"旧中島政次家住宅主屋","kana":"きゅうなかしままさつぐけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.09251381,"lng":130.11505412,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積175㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0070","desc":"多良往還を挟んで中島酒造場主屋の向いに建つ。間口５間半，奥行７間の木造２階建，入母屋造，桟瓦葺とする。外壁は白漆喰塗の大壁造で，２階窓に銅板張の防火扉がつく。内部は東側を土間，西側を居室とする。２階は表を物置，裏を１０畳座敷と次の間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005686"},{"id":"00004472","register_sub_id":"101","register_pk":"105462","name":"呉竹酒造主屋","kana":"くれたけしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2751","lat":33.09225567,"lng":130.11711754,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積400㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0049","desc":"旧長崎街道多良往還に南面して建つ。入母屋造，桟瓦葺，妻入の２階建で，間口７間半奥行８間半の規模。東面下屋部は事務所とし，玄関通り土間西側には４室を一列に並べる。たちの高い正面の構えに特色がある。棟梁は坂井武八で，欅など「各地名材」を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004472"}];
